import {
    type Diagnostics,
    IdentifierShape,
    Plugin,
    PropertyAccessShape,
    Record,
    type Result,
    TemplateExpressionShape,
    ts,
    UnresolvedShape,
} from '@servicenow/sdk-build-core'
import { FDInstanceShape } from '../utils/flow-shapes'
import { ForEachItemShape, PillShape, PillTemplateShape } from '../utils/data-pill-shapes'
import { FLOW_LOGIC } from '../flow-logic/flow-logic-constants'
import { getCallExpressionName } from '../utils'
import { findAncestorByCalleeName, getRecordFromFlowInstaceShape } from '../utils/utils'

function handleRecordType(
    value: Record,
    propertyAccessShape: PropertyAccessShape,
    propertyNames: string[],
    diagnostics: Diagnostics
): Result<PropertyAccessShape> {
    if (!(value.getSource() instanceof FDInstanceShape)) {
        diagnostics.error(
            propertyAccessShape,
            'Invalid data pill: Record references must come from a flow action or subflow output'
        )
        return { success: false as const }
    }
    const pathStr = propertyNames.slice(1).join('.')

    return {
        success: true,
        value: new PillShape({
            source: propertyAccessShape,
            uiId: value.as(Record).get('ui_id').asString().getValue(),
            path: pathStr,
        }),
    }
}

function handleUnresolvedShape(
    value: UnresolvedShape,
    propertyAccessShape: PropertyAccessShape,
    propertyNames: string[],
    diagnostics: Diagnostics
): Result<PropertyAccessShape> {
    const source = value.getSource()
    if (!(source instanceof ts.Node)) {
        diagnostics.error(propertyAccessShape, 'Invalid root source for pill expression')
        return { success: false as const }
    }

    // Todo: if it is any other, below code will take care of it
    const { rootIdentifier, pathStr } = determineRootIdentifierAndPath(propertyNames, diagnostics, propertyAccessShape)

    if (!rootIdentifier) {
        const forEachParamName = getForEachParameterName(propertyAccessShape.getElement(0))
        if (forEachParamName) {
            return {
                success: true,
                value: new PillShape({
                    source: propertyAccessShape,
                    uiId: 'forEach',
                    path: [forEachParamName, ...propertyNames.slice(1)].join('.'),
                }),
            }
        }

        diagnostics.error(propertyAccessShape, 'Invalid pill reference')
        return { success: false }
    }

    return {
        success: true,
        value: new PillShape({
            source: source,
            uiId: rootIdentifier,
            path: pathStr,
        }),
    }
}

export function determineRootIdentifierAndPath(
    propertyNames: string[],
    diagnostics: Diagnostics,
    propertyAccessShape: PropertyAccessShape
) {
    let rootIdentifier = ''
    let pathStr = ''

    switch (propertyNames[1]) {
        case 'inputs': {
            // Detect if inside Action() body → emit {{action.xxx}}, otherwise {{subflow.xxx}}
            const actionAncestor = findAncestorByCalleeName(propertyAccessShape.getOriginalNode(), 'Action')
            rootIdentifier = actionAncestor ? 'action' : 'subflow'
            pathStr = propertyNames.slice(2).join('.')
            break
        }
        case 'flowVariables':
            // For params.flowVariables (schema reference), use 'flowVariables' as identifier with empty path
            // For params.flowVariables.someVar (property access), use 'flow_variable' as identifier
            if (propertyNames.length === 2) {
                // Schema reference: params.flowVariables → {{flowVariables}}
                rootIdentifier = 'flowVariables'
                pathStr = ''
            } else {
                // Property access: params.flowVariables.someVar → {{flow_variable.someVar}}
                rootIdentifier = 'flow_variable'
                pathStr = propertyNames.slice(2).join('.')
            }
            break
        case 'trigger':
            rootIdentifier = 'trigger'
            pathStr = propertyNames.slice(2).join('.')
            break
        case 'outputs':
            // For params.outputs (schema reference in assignSubflowOutputs context), allow it
            // For params.outputs.someOutput (property access), reject it
            if (propertyNames.length === 2) {
                // Schema reference: params.outputs → {{outputs}}
                rootIdentifier = 'outputs'
                pathStr = ''
            } else {
                // Property access: params.outputs.someOutput → error (not allowed)
                diagnostics.error(
                    propertyAccessShape,
                    'Invalid pill reference: Subflow outputs are not allowed as datapills'
                )
                return { rootIdentifier: null, pathStr: null }
            }
            break
        default:
            return { rootIdentifier: null, pathStr: null }
    }

    return { rootIdentifier, pathStr }
}

/**
 * Prefix of a DoInParallel branch-output key (`output_0`, `output_1`, …). The number after it is the branch index.
 * Must match the key `flow-definition-plugin` emits (`output_${branchIndex}`) when it dot-walks a parallel binding.
 */
const OUTPUT_KEY_PREFIX = 'output_'

/**
 * Resolve a property-access pill whose root identifier is bound from a `doInParallel` / `tryCatch` flow-logic
 * construct, walking a nested chain of such bindings down to the referenced action. Handles:
 * - DoInParallel:  `parallel_X.output_N.<…>` (the `output_N` segment selects branch N's arrow)
 * - TryCatch:      `tryCatch_X.<…>` (scans both arms)
 * - Catch param:   `tryOutputs.<…>` (the root is the catch arrow's parameter; scans the paired try arrow)
 *
 * where `<…>` is `actionVarName.…path` for an action declared directly in the branch/arm (e.g.
 * `parallel_X.output_N.actionInstance_Z.field`). An action nested inside an `if`/`forEach`/… container within the
 * branch/arm is not exposed and resolves via the generic resolver instead. Returns a `PillShape` keyed on the matching
 * action `uuid`, or `null` when the chain does not resolve (caller falls back to the generic resolver).
 */
function resolveOuterBindingPill(propertyAccessShape: PropertyAccessShape, propertyNames: string[]): PillShape | null {
    if (propertyNames.length < 3) {
        return null
    }

    const rootElement = propertyAccessShape.getElement(0)
    const rootNode = rootElement.getOriginalNode()
    if (!ts.Node.isNode(rootNode) || !ts.Node.isIdentifier(rootNode)) {
        return null
    }

    // `getDefinitionNodes()` can throw when the ts-morph project is in an inconsistent state.
    let definitionNode: ts.Node | undefined
    try {
        definitionNode = rootNode.getDefinitionNodes()?.[0]
    } catch {
        return null
    }
    if (!definitionNode) {
        return null
    }

    // Catch-arm parameter case: `tryOutputs.actionInstance_N...`. The root resolves to the catch arrow's parameter;
    // the referenced action lives in the *paired try arrow*, so resolve the remaining segments there.
    if (ts.Node.isParameterDeclaration(definitionNode)) {
        const catchArrow = definitionNode.getFirstAncestorByKind(ts.SyntaxKind.ArrowFunction)
        const tryArrow = catchArrow ? getPairedTryArrow(catchArrow) : undefined
        if (!tryArrow) {
            return null
        }

        return resolveWithinArrows([tryArrow], propertyNames.slice(1), propertyAccessShape)
    }

    if (!ts.Node.isVariableDeclaration(definitionNode)) {
        return null
    }

    const initializer = definitionNode.getInitializer()
    if (!initializer || !ts.Node.isCallExpression(initializer)) {
        return null
    }

    // A plain action/subflow root is a same-scope reference — leave it to the generic resolver.
    const rootCallee = getCallExpressionName(initializer)
    if (rootCallee === 'wfa.action' || rootCallee === 'wfa.subflow') {
        return null
    }

    return resolveFromCall(initializer, propertyNames.slice(1), propertyAccessShape)
}

/**
 * Resolve the remaining `segments` against a resolved binding's initializer call. `segments` is the property path
 * *after* the binding name that produced `callExpr`. Dispatches on the call's flow-logic kind and recurses through
 * nested `doInParallel`/`tryCatch` blocks via {@link resolveWithinArrows}.
 */
function resolveFromCall(
    callExpr: ts.CallExpression,
    segments: string[],
    propertyAccessShape: PropertyAccessShape
): PillShape | null {
    const callee = getCallExpressionName(callExpr)
    if (!callee) {
        return null
    }

    if (callee === 'wfa.action' || callee === 'wfa.subflow') {
        return actionPillFromCall(callExpr, segments.join('.'), propertyAccessShape)
    }

    if (callee === FLOW_LOGIC.DO_IN_PARALLEL) {
        // `segments` starts with the `output_N` branch selector.
        const outputKey = segments[0]
        if (!outputKey?.startsWith(OUTPUT_KEY_PREFIX)) {
            return null
        }

        const branchIndex = Number(outputKey.slice(OUTPUT_KEY_PREFIX.length))
        if (!Number.isInteger(branchIndex) || branchIndex < 0) {
            return null
        }

        // arg 0 is the config, branches start at index 1.
        const branchArg = callExpr.getArguments()[branchIndex + 1]
        if (!branchArg || !ts.Node.isArrowFunction(branchArg)) {
            return null
        }

        return resolveWithinArrows([branchArg], segments.slice(1), propertyAccessShape)
    }

    if (callee === FLOW_LOGIC.TRY_CATCH) {
        return resolveWithinArrows(getTryCatchArms(callExpr), segments, propertyAccessShape)
    }

    return null
}

/**
 * Find `const <segments[0]> = <call>` among the top-level statements of any of `arrows`, then resolve the rest of the
 * path against that binding's call (recursing through nested blocks/containers). Returns `null` if no such binding is
 * found or the remainder does not resolve.
 */
function resolveWithinArrows(
    arrows: ts.ArrowFunction[],
    segments: string[],
    propertyAccessShape: PropertyAccessShape
): PillShape | null {
    const name = segments[0]
    if (!name) {
        return null
    }

    for (const arrow of arrows) {
        const body = arrow.getBody()
        if (!ts.Node.isBlock(body)) {
            continue
        }

        for (const statement of body.getStatements()) {
            if (!ts.Node.isVariableStatement(statement)) {
                continue
            }

            const [decl] = statement.getDeclarations()
            if (!decl || decl.getName() !== name) {
                continue
            }

            const init = decl.getInitializer()
            if (!init || !ts.Node.isCallExpression(init)) {
                continue
            }

            const pill = resolveFromCall(init, segments.slice(1), propertyAccessShape)
            if (pill) {
                return pill
            }
        }
    }

    return null
}

/** Build a `PillShape` keyed on an action/subflow call's `uuid` (config arg 1) with the given remaining `path`. */
function actionPillFromCall(
    actionCall: ts.CallExpression,
    path: string,
    propertyAccessShape: PropertyAccessShape
): PillShape | null {
    const configArg = actionCall.getArguments()[1]
    if (!configArg || !ts.Node.isObjectLiteralExpression(configArg)) {
        return null
    }

    const uuidProp = configArg.getProperty('uuid')
    if (!uuidProp || !ts.Node.isPropertyAssignment(uuidProp)) {
        return null
    }

    const uuidInit = uuidProp.getInitializer()
    if (!uuidInit || !ts.Node.isStringLiteral(uuidInit)) {
        return null
    }

    return new PillShape({ source: propertyAccessShape, uiId: uuidInit.getLiteralValue(), path })
}

/** The `try` and `catch` arm arrows of a `tryCatch(config, { try, catch })` call, in that order. */
function getTryCatchArms(callExpr: ts.CallExpression): ts.ArrowFunction[] {
    const arms: ts.ArrowFunction[] = []
    const handlers = callExpr.getArguments()[1]
    if (handlers && ts.Node.isObjectLiteralExpression(handlers)) {
        for (const propName of ['try', 'catch'] as const) {
            const prop = handlers.getProperty(propName)
            if (prop && ts.Node.isPropertyAssignment(prop)) {
                const init = prop.getInitializer()
                if (init && ts.Node.isArrowFunction(init)) {
                    arms.push(init)
                }
            }
        }
    }
    return arms
}

/**
 * Given the catch arrow of a `tryCatch`, return the paired `try` arrow (the sibling `try:` property's arrow function
 * in the same handlers object literal). Returns `undefined` if the arrow isn't a tryCatch catch arm.
 */
function getPairedTryArrow(catchArrow: ts.ArrowFunction): ts.ArrowFunction | undefined {
    const prop = catchArrow.getParentIfKind(ts.SyntaxKind.PropertyAssignment)
    if (!prop || prop.getName() !== 'catch') {
        return undefined
    }
    const handlers = prop.getParentIfKind(ts.SyntaxKind.ObjectLiteralExpression)
    if (!handlers) {
        return undefined
    }
    const tryProp = handlers.getProperty('try')
    if (tryProp && ts.Node.isPropertyAssignment(tryProp)) {
        const init = tryProp.getInitializer()
        if (init && ts.Node.isArrowFunction(init)) {
            return init
        }
    }
    return undefined
}

/**
 * Get the parameter name from a forEach arrow function
 * Returns the actual parameter name (e.g., 'dept', 'category', 'item') instead of generic 'item'
 * Returns null if the identifier is not a forEach parameter
 */
function getForEachParameterName(identifierShape: IdentifierShape): string | null {
    const param = identifierShape.getOriginalNode().asKind(ts.SyntaxKind.Identifier)?.getDefinitionNodes()?.[0]
    const parentLogicNode = param
        ?.getParentIfKind(ts.SyntaxKind.ArrowFunction)
        ?.getParentIfKind(ts.SyntaxKind.CallExpression)

    if (!parentLogicNode || getCallExpressionName(parentLogicNode) !== FLOW_LOGIC.FOR_EACH) {
        return null
    }

    // Get the actual parameter name from the identifier
    return identifierShape.getName()
}

export const DataPillPlugin = Plugin.create({
    name: 'DataPillPlugin',
    noTelemetry: true,
    shapes: [
        {
            shape: PropertyAccessShape,
            fileTypes: ['fluent'],
            async toSubclass(propertyAccessShape, { diagnostics, transform }): Promise<Result<PropertyAccessShape>> {
                // Decompose PropertyAccessExpression into root identifier and remaining path
                const ancestor = findAncestorByCalleeName(propertyAccessShape.getOriginalNode(), 'wfa.dataPill')
                if (!ancestor) {
                    diagnostics.error(propertyAccessShape, 'Datapill reference must be inside a wfa.dataPill call')
                    return { success: false }
                }
                const propertyNames: string[] = []
                propertyAccessShape.getElements().forEach((element) => {
                    if (element instanceof IdentifierShape) {
                        propertyNames.push(element.getName())
                    }
                })

                // Property access through an outer-scope binding emitted by flow-logic-plugin for a `doInParallel`
                // parallel branch (`parallel_X.output_N....`) or `tryCatch` arm (`tryCatch_X....`). Resolve the inner
                // action directly from the binding's declaration and produce a UUID-based pill.
                const outerBindingPill = resolveOuterBindingPill(propertyAccessShape, propertyNames)
                if (outerBindingPill) {
                    return { success: true, value: outerBindingPill }
                }

                const value = propertyAccessShape.getElement(0).resolve()
                if (value.is(UnresolvedShape)) {
                    return handleUnresolvedShape(value, propertyAccessShape, propertyNames, diagnostics)
                }
                const record = await getRecordFromFlowInstaceShape(value, transform)

                if (record?.is(Record)) {
                    return handleRecordType(record, propertyAccessShape, propertyNames, diagnostics)
                }

                return { success: false }
            },
        },
        {
            shape: TemplateExpressionShape,
            fileTypes: ['fluent'],
            async toSubclass(shape: TemplateExpressionShape, { transform }): Promise<Result<TemplateExpressionShape>> {
                const parts: (string | PillShape)[] = []
                const leadingText = shape.getLiteralText()

                if (leadingText.length > 0) {
                    parts.push(leadingText)
                }

                for (const span of shape.getSpans()) {
                    const expr = span.getExpression()
                    const literalText = span.getLiteralText()

                    const pillShape = expr.is([PropertyAccessShape, IdentifierShape])
                        ? await transform.toSubclass(expr, DataPillPlugin) // In case of PropertyAccessShape call the toSubclass() again, which calls above handler
                        : undefined

                    if (pillShape) {
                        if (pillShape instanceof PillShape) {
                            // do not call getValue() for trigger, as this will be handled in flow-instance-plugin
                            if (pillShape.getRootIdentifier() === 'trigger') {
                                parts.push(pillShape)
                            } else {
                                parts.push(pillShape.getValue())
                            }
                            parts.push(literalText)
                        }

                        if (pillShape instanceof ForEachItemShape) {
                            parts.push(pillShape.getValue())
                            parts.push(literalText)
                        }
                    }
                }

                return {
                    success: true,
                    value: new PillTemplateShape({
                        source: shape,
                        parts,
                    }),
                }
            },
        },
        {
            shape: IdentifierShape,
            fileTypes: ['fluent'],
            async toSubclass(identifierShape) {
                const forEachParamName = getForEachParameterName(identifierShape)
                if (!forEachParamName) {
                    return { success: false }
                }

                return {
                    success: true,
                    value: new ForEachItemShape({
                        source: identifierShape,
                        uiId: 'forEach',
                        path: forEachParamName,
                    }),
                }
            },
        },
    ],
})
