/**
 * Configuration parameters for Do The Following Until flow logic
 */
type DoTheFollowingParams = Now.Internal.WithID<{
    label?: string
    annotation?: string
}>

/**
 * Executes the body repeatedly until the end condition is met (do-while semantics).
 *
 * The body always runs at least once. The condition is set by calling `wfa.flowLogic.until(...)`
 * as the body's last statement, which means it is evaluated after all body
 * actions run and can reference their outputs.
 *
 * @param params - Configuration with $id, optional label and annotation
 * @param body - Function body to execute on each iteration; must call `wfa.flowLogic.until(...)`
 *
 * @example
 * ```typescript
 * wfa.flowLogic.doTheFollowing(
 *   { $id: Now.ID['do_until_1'], label: 'Retry until resolved', annotation: 'Retry loop' },
 *   () => {
 *     const result = wfa.action(someAction, { $id: Now.ID['step_1'] }, { ... })
 *     wfa.flowLogic.until(`${wfa.dataPill(result.output.status, 'string')}=done`)
 *   }
 * )
 * ```
 */
export function DoTheFollowing(_params: DoTheFollowingParams, _body?: () => void): void {
    return
}

/**
 * Marks the exit condition for a `wfa.flowLogic.doTheFollowing` loop body.
 *
 * Call this as the last statement in the loop body — do not `return` it. Because it lives
 * inside the body, it can reference action outputs declared earlier in the same body
 * (do-while semantics: the condition is checked after the body runs).
 *
 * @param value - The condition string (may contain `wfa.dataPill(...)` references)
 */
export function until(value: string): string {
    return value
}
