import {
    type Diagnostics,
    PropertyAccessShape,
    TemplateExpressionShape,
    TemplateSpanShape,
    type Source,
} from '@servicenow/sdk-build-core'

export const PILL_REGEX = /\{\{[^}]+\}\}/g

/**
 * Detects if a string contains data pill expressions
 * @param value - String to check for pill patterns
 * @returns 'simple' for single pill, 'template' for text with pills, 'none' for no pills
 */
export function detectPillPattern(value: string): 'simple' | 'template' | 'none' {
    if (!value || typeof value !== 'string') {
        return 'none'
    }

    const matches = value.match(PILL_REGEX)

    if (!matches) {
        return 'none'
    }
    // Simple pill: entire string is a single pill (with optional whitespace)
    if (matches.length === 1 && value.trim() === matches[0].trim()) {
        return 'simple'
    }
    // Template: contains one or more pills mixed with text
    return 'template'
}

/**
 * Represents a parsed data pill expression
 */
export interface ParsedPill {
    prefix: string // "trigger", "flow_variable", "inputs", "outputs", or UUID
    path: string // "table_name", "array", etc.
    fullMatch: string
}

/**
 * Parses a single pill expression
 * @param pillString - Input like "{{trigger.table_name}}"
 * @param allowSchemaReferences - If true, allows schema references without dots (e.g., {{flowVariables}}, {{outputs}}). Used during XML-to-Fluent conversion. Default: false.
 * @returns Parsed components or null if invalid
 * @example
 * parseSinglePill("{{trigger.table_name}}")
 * // Returns: { prefix: "trigger", path: "table_name", fullMatch: "{{trigger.table_name}}" }
 */
export function parseSinglePill(pillString: string, allowSchemaReferences: boolean = false): ParsedPill | null {
    // Trim whitespace to handle pills with leading/trailing spaces
    const trimmed = pillString.trim()

    // Remove {{ and }} - match the entire pattern and extract content in between
    const match = trimmed.match(/^\{\{(.*)\}\}$/)
    if (!match) {
        return null
    }
    let content = match[1]?.trim()

    if (!content) {
        return null
    }

    // Strip type annotation if present (e.g., "trigger.name|string" → "trigger.name")
    // ServiceNow stores datapills with type annotations that need to be removed
    const pipeIndex = content.indexOf('|')
    if (pipeIndex !== -1) {
        content = content.substring(0, pipeIndex).trim()
    }

    // Split by first dot: "trigger.table_name" → ["trigger", "table_name"]
    const dotIndex = content.indexOf('.')

    if (dotIndex === -1) {
        // No dot - check if this is allowed based on context
        if (!allowSchemaReferences) {
            // During Fluent-to-XML or test parsing, pills without dots are invalid
            return null
        }

        // During XML-to-Fluent: only allow valid schema references
        const validSchemaReferences = ['flowVariables', 'outputs']

        if (!validSchemaReferences.includes(content)) {
            // Invalid pill format - only flowVariables and outputs are valid schema references
            return null
        }

        // Return with empty path to indicate this is a schema reference, not a property access
        return {
            prefix: content,
            path: '',
            fullMatch: trimmed,
        }
    }

    const prefix = content.substring(0, dotIndex)
    const path = content.substring(dotIndex + 1)

    return {
        prefix,
        path,
        fullMatch: trimmed,
    }
}

/**
 * Maps pill prefix to TypeScript property access root
 * @param prefix - Pill prefix like "trigger", "flow_variable", "subflow", or trigger-specific prefixes like "Created_1", "Updated_1", etc.
 * @param parameterName - Optional parameter name to use instead of "params" (default: "params")
 * @returns TypeScript path like "params.trigger" or null if not a known semantic prefix
 */
export function mapPillPrefixToTsRoot(prefix: string, parameterName: string = 'params'): string | null {
    const mapping: Record<string, string> = {
        trigger: `${parameterName}.trigger`,
        flow_variable: `${parameterName}.flowVariables`,
        flowVariables: `${parameterName}.flowVariables`, // Schema reference (no property access)
        inputs: `${parameterName}.inputs`,
        outputs: `${parameterName}.outputs`, // Schema reference (no property access)
        subflow: `${parameterName}.inputs`, // ServiceNow uses {{subflow.x}} for subflow inputs
        action: `${parameterName}.inputs`, // ServiceNow uses {{action.x}} for action inputs → params.inputs.x

        // Record triggers (prefixed with trigger name + _1)
        Created_1: `${parameterName}.trigger`,
        Updated_1: `${parameterName}.trigger`,
        'Created or Updated_1': `${parameterName}.trigger`,

        // Scheduled triggers
        Daily_1: `${parameterName}.trigger`,
        Weekly_1: `${parameterName}.trigger`,
        Monthly_1: `${parameterName}.trigger`,
        Repeat_1: `${parameterName}.trigger`,
        'Run Once_1': `${parameterName}.trigger`,

        // Application triggers
        'Inbound Email_1': `${parameterName}.trigger`,
        'Knowledge Management_1': `${parameterName}.trigger`,
        'Remote Table Query_1': `${parameterName}.trigger`,
        'REST API - Asynchronous_1': `${parameterName}.trigger`,
        'Service Catalog_1': `${parameterName}.trigger`,
        'SLA Task_1': `${parameterName}.trigger`,
    }

    return mapping[prefix] ?? null
}

/**
 * Checks if prefix is a UUID (action/subflow instance reference)
 * @param prefix - Prefix to check
 * @returns True if the prefix matches UUID format
 */
export function isUuidPrefix(prefix: string): boolean {
    // UUID format: xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx
    const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i
    return uuidRegex.test(prefix)
}

/**
 * Creates a PropertyAccessShape from a semantic path like "params.trigger.table_name"
 * @param path - Dot-separated property path
 * @param source - Source for the shape
 * @returns PropertyAccessShape or null if path is invalid
 */
export function createPropertyAccessFromPath(path: string, source: Source): PropertyAccessShape | null {
    const parts = path.split('.')

    if (parts.length < 2) {
        return null
    }

    // PropertyAccessShape constructor accepts strings and handles conversion internally
    // Cast through unknown to satisfy TypeScript (we know parts.length >= 2 from check above)
    return new PropertyAccessShape({
        source,
        elements: parts as unknown as readonly [string, string, ...string[]],
    })
}

/**
 * Creates a TemplateExpressionShape from a template string with pills
 * @param templateStr - Input like "Hello {{trigger.name}}, your ID is {{trigger.sys_id}}"
 * @param source - Source for the shape
 * @param parameterName - Optional parameter name to use instead of "params" (e.g., from ArrowFunction)
 * @param allowSchemaReferences - If true, allows schema references without dots. Used during XML-to-Fluent conversion. Default: false.
 * @returns TemplateExpressionShape or null if no valid pills found
 *
 * @example
 * createTemplateExpressionFromPillString(
 *   "Lead text {{trigger.name}} trail text",
 *   record,
 *   diagnostics
 * )
 * // Creates: `Lead text ${params.trigger.name} trail text`
 */
export function createTemplateExpressionFromPillString(
    templateStr: string,
    source: Source,
    parameterName?: string,
    allowSchemaReferences: boolean = false
): TemplateExpressionShape | null {
    const pillRegex = /\{\{[^}]+\}\}/g

    // Collect all recognized pills with their positions
    const recognizedPills: { propAccess: PropertyAccessShape; matchStart: number; matchEnd: number }[] = []
    let match: RegExpExecArray | null

    while ((match = pillRegex.exec(templateStr)) !== null) {
        const parsed = parseSinglePill(match[0], allowSchemaReferences)
        if (!parsed) {
            continue
        }

        const tsRoot = mapPillPrefixToTsRoot(parsed.prefix, parameterName)
        const fullPath = tsRoot ? (parsed.path === '' ? tsRoot : `${tsRoot}.${parsed.path}`) : null
        const propAccess = fullPath ? createPropertyAccessFromPath(fullPath, source) : null

        if (propAccess) {
            recognizedPills.push({
                propAccess,
                matchStart: match.index ?? 0,
                matchEnd: (match.index ?? 0) + match[0].length,
            })
        }
        // Unrecognized pills (step, UUID, unknown prefix) are not collected here.
        // Their raw text is preserved in the literal text segments between recognized pills.
    }

    if (recognizedPills.length === 0) {
        return null
    }

    // Build template: head is text before first pill, each span has expression + text after it
    const firstPillStart = recognizedPills[0]?.matchStart ?? 0
    const head = templateStr.substring(0, firstPillStart)
    const spans: TemplateSpanShape[] = []

    for (const [i, pill] of recognizedPills.entries()) {
        const nextPill = recognizedPills[i + 1]
        // Literal text after this pill extends to the start of the next recognized pill
        // (or end of string). This preserves raw text of any unrecognized pills in between.
        const literalAfter = nextPill
            ? templateStr.substring(pill.matchEnd, nextPill.matchStart)
            : templateStr.substring(pill.matchEnd)

        spans.push(
            new TemplateSpanShape({
                source,
                expression: pill.propAccess,
                literalText: literalAfter,
            })
        )
    }

    return new TemplateExpressionShape({
        source,
        literalText: head,
        spans,
    })
}

/**
 * Converts a data pill string from XML to a TypeScript Shape
 * Handles both simple pills and template expressions with pills
 *
 * @param value - String value from XML (may contain pills)
 * @param source - Source for shape creation
 * @param diagnostics - Diagnostics instance (currently unused but kept for future use)
 * @param parameterName - Optional parameter name to use instead of "params" (e.g., from ArrowFunction)
 * @param allowSchemaReferences - If true, allows schema references without dots (e.g., {{flowVariables}}, {{outputs}}). Should be true during XML-to-Fluent conversion. Default: true.
 * @returns PropertyAccessShape, TemplateExpressionShape, or undefined if not a pill
 *
 * @example
 * // Simple pill
 * convertPillStringToShape("{{trigger.table_name}}", record, diagnostics)
 * // Returns: PropertyAccessShape for params.trigger.table_name
 *
 * // Template
 * convertPillStringToShape("Hello {{trigger.name}}", record, diagnostics)
 * // Returns: TemplateExpressionShape for `Hello ${params.trigger.name}`
 *
 * // Not a pill
 * convertPillStringToShape("just text", record, diagnostics)
 * // Returns: undefined
 */
export function convertPillStringToShape(
    value: string,
    source: Source,
    _diagnostics: Diagnostics,
    parameterName?: string,
    allowSchemaReferences: boolean = true
): PropertyAccessShape | TemplateExpressionShape | undefined {
    const patternType = detectPillPattern(value)

    if (patternType === 'none') {
        return undefined // Not a pill, handle normally
    }

    if (patternType === 'simple') {
        // Simple pill: "{{trigger.table_name}}"
        const parsed = parseSinglePill(value, allowSchemaReferences)

        if (!parsed) {
            // Invalid pill format - return undefined to fall back to normal value handling
            return undefined
        }

        if (isUuidPrefix(parsed.prefix)) {
            // UUID-based pill - not supported yet (Phase 3)
            // Return undefined to fall back to string literal
            return undefined
        }

        const tsRoot = mapPillPrefixToTsRoot(parsed.prefix, parameterName)

        if (!tsRoot) {
            // Unknown pill prefix - return undefined to fall back to normal value handling
            return undefined
        }

        // Handle schema references (no property access) like {{flowVariables}} or {{outputs}}
        if (parsed.path === '') {
            // This is a schema reference - tsRoot already contains the full path (e.g., "params.flowVariables")
            const propAccess = createPropertyAccessFromPath(tsRoot, source)
            if (!propAccess) {
                return undefined
            }
            return propAccess
        }

        // Handle property access like {{trigger.table_name}}
        const fullPath = `${tsRoot}.${parsed.path}`
        const propAccess = createPropertyAccessFromPath(fullPath, source)

        if (!propAccess) {
            // Failed to create PropertyAccess - return undefined to fall back
            return undefined
        }

        return propAccess
    }

    if (patternType === 'template') {
        // Template with pills: "Hello {{trigger.name}}"
        const templateExpr = createTemplateExpressionFromPillString(value, source, parameterName, allowSchemaReferences)

        if (!templateExpr) {
            // Failed to parse template - return undefined to fall back to normal value
            return undefined
        }

        return templateExpr
    }

    return undefined
}
