import { Action } from '../../../Action'
import {
    FieldNameColumn,
    ScheduleDateTimeColumn,
    TableNameColumn,
    DocumentIdColumn,
    StringColumn,
    ChoiceColumn,
    ApprovalRulesColumn,
} from '@servicenow/sdk-core/runtime/db'

export const askForApproval = Action({
    $id: 'f8f2e9920b10030085c083eb37673abd',
    name: 'Ask For Approval',
    description:
        'Create Approvals on any record in the ServiceNow system. You can configure a rule set for an approval, rejection, or cancellation. You can add additional rule sets to further define approval rule(s) and rejection rule(s). If a Due Date is added to an approval, it automatically approves, rejects, or cancels the approvals if the approvers have not responded.',
    inputs: {
        approval_field: FieldNameColumn({
            label: 'Approval Field',
            maxLength: 8000,
        }),
        journal_field: FieldNameColumn({
            label: 'Journal Field',
            maxLength: 8000,
        }),
        due_date: ScheduleDateTimeColumn({
            label: 'Due Date',
        }),
        approval_conditions: ApprovalRulesColumn({
            label: 'Approval Conditions',
            mandatory: true,
            maxLength: 8000,
        }),
        table: TableNameColumn({
            label: 'Table',
        }),
        record: DocumentIdColumn({
            label: 'Record',
            mandatory: true,
            dependent: 'table',
        }),
        approval_reason: StringColumn({
            label: 'Approval Reason',
            maxLength: 160,
        }),
    },
    outputs: {
        approval_state: ChoiceColumn({
            label: 'Approval State',
            choices: {
                'not requested': {
                    label: 'Not Yet Requested',
                },
                rejected: {
                    label: 'Rejected',
                    sequence: 3,
                },
                approved: {
                    label: 'Approved',
                    sequence: 2,
                },
                not_required: {
                    label: 'No Longer Required',
                    sequence: 5,
                },
                requested: {
                    label: 'Requested',
                    sequence: 1,
                },
                cancelled: {
                    label: 'Cancelled',
                    sequence: 4,
                },
                skipped: {
                    label: 'Skipped',
                    sequence: 6,
                },
            },
        }),
    },
})
