import {
    WfaDataPillPlugin,
    FlowDefinitionPlugin,
    InlineScriptPlugin,
    ApprovalRulesPlugin,
    StepDefinitionPlugin,
    StepInstancePlugin,
    ActionDefinitionPlugin,
    TriggerPlugin,
    FlowDiagnosticsPlugin,
} from './plugin'

export * from './api'

// FlowInstancePlugin, TriggerInstancePlugin, and FlowLogicPlugin are invoked
// indirectly via explicit `transform.toRecord(shape, ThatPlugin)` calls from
// FlowDefinitionPlugin and must not be registered as top-level handlers.
// Registering them globally causes their CallExpressionShape handlers to pre-
// transform Flow's trigger argument into a Record during CallExpressionPlugin's
// recursive arg resolution, which breaks FlowDefinitionPlugin's
// `getArgument(1).as(CallExpressionShape)` cast.
// Invocation order is reversed on fluent side.
export default [
    FlowDiagnosticsPlugin,
    TriggerPlugin,
    ActionDefinitionPlugin,
    StepInstancePlugin,
    StepDefinitionPlugin,
    ApprovalRulesPlugin,
    InlineScriptPlugin,
    FlowDefinitionPlugin,
    WfaDataPillPlugin,
]
