import { ArrowFunctionShape } from '@servicenow/sdk-build-plugins'
import {
    CallExpressionShape,
    IdentifierShape,
    ObjectShape,
    Record,
    type Shape,
    VariableStatementShape,
    gunzipSync,
} from '@servicenow/sdk-build-core'
import {
    DO_IN_PARALLEL_BLOCK_SYS_ID,
    FLOW_LOGIC,
    FLOW_LOGIC_SYS_ID_MAP,
    TRY_CATCH_CATCH_SYS_ID,
} from '../flow-logic/flow-logic-constants'
import { PARALLEL_ORDER_SEPARATOR } from '../constants/flow-plugin-constants'
import { makeArrow, uuidToRecordMap } from './datapill-transformer'

/**
 * Outer-scope output bindings for `doInParallel` branches and `tryCatch` arms (DEF0837398).
 *
 * When an action nested inside a parallel branch or a try/catch arm exposes its output to the surrounding flow, the
 * generated `.now.ts` dot-walks through an outer binding (`parallel_X.output_N.action…`) or, for a catch arm
 * referencing a try-arm action, through the catch arrow's `tryOutputs` parameter. This module owns all of that
 * machinery — building the binding/ancestor/catch-param maps, stripping bindings that aren't referenced from outside
 * their block, and injecting the catch parameter — keeping it out of the core datapill transformer. The core
 * transformer threads an `OuterBindingContext` (below) into pill resolution and otherwise stays agnostic to this logic.
 */

/**
 * Metadata for the outer-scope binding emitted by `flow-logic-plugin` for an action nested inside a `doInParallel`
 * parallel branch or a `tryCatch` arm.
 *
 * - `outerName`: the variable name in the outer scope (`parallelBranch_X`, `tryCatch_Y`).
 * - `branchUiId`: the `ui_id` of the parallel branch / try / catch arm that owns the action. References originating
 *    inside the same branch still resolve to the bare action identifier. The outer binding is not assigned until
 *    after the doInParallel/tryCatch call returns, so referencing it from inside the arrow function body would fail at
 *    runtime.
 *
 * Callers resolve pills with `shouldUseOuterBinding(info, sourceAncestorUiIds)` (below).
 */
export interface OuterBindingInfo {
    outerName: string
    branchUiId: string
    branchIndex: number
}

/**
 * Threaded through pill resolution so a UUID-based pill can decide whether the source record sits outside the target's
 * branch (in which case the outer binding must be dot-walked) or inside it (the bare identifier is in scope).
 *
 * `sourceAncestorChain` is recomputed at each `processInstanceForDatapills` call to reflect the current instance whose
 * props are being processed. The set contains the source instance's own `ui_id` and every ancestor `ui_id` walked
 * through `parent_ui_id`. When a target action's `branchUiId` is in this set, source and target share scope and the bare identifier works.
 */
export interface OuterBindingContext {
    outerBindingMap: Map<string, OuterBindingInfo>
    ancestorChainMap: Map<string, Set<string>>
    sourceAncestorChain?: Set<string>
    // Maps a try-arm action UUID to the catch arm that references it. When a pill in the catch arm references a
    // try-arm action, it resolves to `<paramName>.<actionInstance_N>` — a dot-walk through the catch arrow's
    // parameter — instead of the self-referential outer `tryCatch_X` binding (which the build cannot resolve).
    catchParamMap?: Map<string, CatchParamInfo>
}

/**
 * The catch arm of a `tryCatch` receives the try arm's outputs as a parameter. When a catch-arm pill references a
 * try-arm action, this records the parameter name to dot-walk through and the catch arm's `ui_id` (so the resolver
 * only applies the dot-walk for references that actually originate inside that catch arm).
 */
export interface CatchParamInfo {
    paramName: string
    catchArmUiId: string
    tryUiId: string
}

/** Fixed the parameter name for the try-arm outputs passed into a catch arm. */
const CATCH_OUTPUTS_PARAM = 'tryOutputs'

/** The callee of a `const x = wfa.flowLogic.<callee>(...)` binding, or undefined if `shape` isn't such a binding. */
function bindingCallee(shape: Shape | undefined): string | undefined {
    if (!(shape instanceof VariableStatementShape)) {
        return undefined
    }

    const init = shape.getInitializer()
    return init instanceof CallExpressionShape ? init.getCallee() : undefined
}

/** Return a copy of `shape` with its initializer replaced, preserving the variable name and export flag. */
function withInitializer(shape: VariableStatementShape, initializer: Shape): VariableStatementShape {
    return new VariableStatementShape({
        source: shape.getSource(),
        variableName: shape.getVariableName(),
        initializer,
        isExported: shape.isExported(),
    })
}

/**
 * Destructure a `wfa.flowLogic.tryCatch(config, { try, catch })` call into its config arg, handlers object, and the two
 * arm arrows. Returns undefined if the call isn't a well-formed tryCatch (missing config / handlers / arm arrows).
 */
function tryCatchArms(
    callExpr: CallExpressionShape
):
    | { configArg: Shape; handlersArg: ObjectShape; tryArrow: ArrowFunctionShape; catchArrow: ArrowFunctionShape }
    | undefined {
    const args = callExpr.getArguments()
    const configArg = args[0]
    const handlersArg = args[1]
    if (!configArg || !(handlersArg instanceof ObjectShape)) {
        return undefined
    }

    const tryArrow = handlersArg.get('try')
    const catchArrow = handlersArg.get('catch')
    if (!(tryArrow instanceof ArrowFunctionShape) || !(catchArrow instanceof ArrowFunctionShape)) {
        return undefined
    }

    return { configArg, handlersArg, tryArrow, catchArrow }
}

/**
 * If `shape` is a `const x = wfa.flowLogic.<callee>(...)` binding whose initializer callee matches `callee`, return the
 * bound variable name (`parallel_1`, `tryCatch_1`). Returns undefined otherwise.
 */
function outerBindingNameFor(shape: Shape | undefined, callee: FLOW_LOGIC): string | undefined {
    if (!(shape instanceof VariableStatementShape) || bindingCallee(shape) !== callee) {
        return undefined
    }

    return shape.getVariableName().getName()
}

/**
 * Build the outer-binding metadata for actions that are direct children of `doInParallel` branches or `tryCatch` arms.
 * An action nested inside an `if`/`elseIf`/`else`/`forEach`/`doTheFollowing` container is intentionally left unbound —
 * its output is not exposed to the outer scope, so its pill resolves to a bare identifier (the platform does not allow
 * referencing a step inside such a container from outside it).
 *
 * @param recordToShapeMap - Map of instance records to their corresponding shapes.
 * @param allInstances - All flow instance records (action, subflow, flow-logic).
 */
export function buildOuterBindingMap(
    recordToShapeMap: Map<Record, Shape>,
    allInstances: ReadonlyArray<Record>
): Map<string, OuterBindingInfo> {
    const result = new Map<string, OuterBindingInfo>()
    if (allInstances.length === 0) {
        return result
    }

    const tryCatchLogicId = FLOW_LOGIC_SYS_ID_MAP[FLOW_LOGIC.TRY_CATCH]
    const uiOf = (r: Record): string | undefined => r.get('ui_id')?.ifString()?.getValue()
    const parentOf = (r: Record): string | undefined => r.get('parent_ui_id')?.ifString()?.getValue()

    // Returns the logic_definition for flow-logic instances only (undefined for other tables / missing values), so a
    // single equality check below doubles as the table guard.
    const logicDefOf = (r: Record): string | undefined =>
        r.getTable() === 'sys_hub_flow_logic_instance_v2'
            ? r.get('logic_definition')?.ifString()?.getValue()
            : undefined

    // Index records by ui_id and group parallel branches under their parent (main `doInParallel`) ui_id so the branch
    // index can be looked up without re-filtering all instances per branch.
    const recordByUiId = new Map<string, Record>()
    const parallelBranchesByMain = new Map<string, Record[]>()

    for (const inst of allInstances) {
        const ui = uiOf(inst)
        if (ui) {
            recordByUiId.set(ui, inst)
        }

        const mainUiId = logicDefOf(inst) === DO_IN_PARALLEL_BLOCK_SYS_ID ? parentOf(inst) : undefined
        if (mainUiId) {
            const siblings = parallelBranchesByMain.get(mainUiId) ?? []
            siblings.push(inst)
            parallelBranchesByMain.set(mainUiId, siblings)
        }
    }

    for (const siblings of parallelBranchesByMain.values()) {
        siblings.sort(compareOrder)
    }

    // ui_id of a branch / try / catch arm → the outer binding its inner actions dot-walk through. `branchIndex` is the
    // `output_N` index for a `doInParallel` branch, or -1 for a `tryCatch` arm (which dot-walks directly, no output_N).
    const branchBindings = new Map<string, OuterBindingInfo>()

    for (const inst of allInstances) {
        const logicDef = logicDefOf(inst)

        if (logicDef === DO_IN_PARALLEL_BLOCK_SYS_ID) {
            const branchUiId = uiOf(inst)
            const mainUiId = parentOf(inst)
            const mainRecord = mainUiId ? recordByUiId.get(mainUiId) : undefined
            const outerName =
                mainRecord && outerBindingNameFor(recordToShapeMap.get(mainRecord), FLOW_LOGIC.DO_IN_PARALLEL)
            const branchIndex = mainUiId ? (parallelBranchesByMain.get(mainUiId) ?? []).indexOf(inst) : -1

            if (branchUiId && outerName && branchIndex >= 0) {
                branchBindings.set(branchUiId, { outerName, branchUiId, branchIndex })
            }
        } else if (tryCatchLogicId && logicDef === tryCatchLogicId) {
            const tryUiId = uiOf(inst)
            const outerName = outerBindingNameFor(recordToShapeMap.get(inst), FLOW_LOGIC.TRY_CATCH)
            if (!tryUiId || !outerName) {
                continue
            }

            branchBindings.set(tryUiId, { outerName, branchUiId: tryUiId, branchIndex: -1 })

            // The catch arm shares the same binding; both arms dot-walk through `tryCatch_X`.
            const catchUiId = uiOf(
                allInstances.find(
                    (r) => logicDefOf(r) === TRY_CATCH_CATCH_SYS_ID && r.get('connected_to')?.getValue() === tryUiId
                ) ?? inst
            )

            if (catchUiId && catchUiId !== tryUiId) {
                branchBindings.set(catchUiId, { outerName, branchUiId: catchUiId, branchIndex: -1 })
            }
        }
    }

    if (branchBindings.size === 0) {
        return result
    }

    for (const [uuid, record] of uuidToRecordMap.entries()) {
        const parentUiId = parentOf(record)
        if (!parentUiId) {
            continue
        }

        // Only an action that is a DIRECT child of a doInParallel branch / tryCatch arm gets an outer binding. When an
        // `if`/`elseIf`/`else`/`forEach`/`doTheFollowing` container sits between the action and its branch/arm, the
        // UUID is left unbound and generic pill resolution emits the bare identifier — an action nested inside such a
        // container is not exposed to the outer scope, matching Flow Designer, where it cannot be referenced there.
        const direct = branchBindings.get(parentUiId)
        if (direct) {
            result.set(uuid, direct)
        }
    }

    return result
}

/**
 * Detect a reference that cannot be represented as an in-scope Fluent binding: an action inside a `tryCatch` that is
 * itself nested inside another `tryCatch` arm, referenced from a source outside the outer block. The action's outer
 * binding (`const tryCatch_X = wfa.flowLogic.tryCatch(...)`) is declared inside the outer arm, so it is not in lexical
 * scope at such a reference site — emitting the dot-walk would produce an unresolvable identifier (which the SDK's
 * unused-code cleanup then deletes along with the inner steps). When this returns true the caller should fall back to
 * the generic Record() API for the whole flow rather than emit broken Fluent.
 *
 * Single-level output bindings (a block at the flow top level, the supported hoisting case) are always representable —
 * their `const` sits at the flow root, reachable from any downstream step — so they never trigger this. Only nested
 * `tryCatch` is considered: a nested `doInParallel` is prevented upstream by a diagnostic, so `doInParallel` bindings
 * are skipped here.
 */
export function detectUnrepresentableOuterBinding(
    outerBindingMap: Map<string, OuterBindingInfo>,
    ancestorChainMap: Map<string, Set<string>>,
    allInstances: ReadonlyArray<Record>
): boolean {
    if (outerBindingMap.size === 0) {
        return false
    }

    const recordByUiId = new Map<string, Record>()
    for (const inst of allInstances) {
        const ui = inst.get('ui_id')?.ifString()?.getValue()
        if (ui) {
            recordByUiId.set(ui, inst)
        }
    }

    // The `ui_id` of the scope holding the tryCatch's `const tryCatch_X` — the try record's parent. Undefined for a
    // tryCatch at the flow top level, whose binding is reachable from anywhere.
    const bindingScopeOf = (info: OuterBindingInfo): string | undefined => {
        const branchRecord = recordByUiId.get(info.branchUiId)
        if (!branchRecord) {
            return undefined
        }

        // The `const` is emitted at the try record; for a catch arm, the paired try is its `connected_to`.
        const tryRecord =
            branchRecord.get('logic_definition')?.ifString()?.getValue() === TRY_CATCH_CATCH_SYS_ID
                ? recordByUiId.get(branchRecord.get('connected_to')?.ifString()?.getValue() ?? '')
                : branchRecord

        return tryRecord?.get('parent_ui_id')?.ifString()?.getValue() || undefined
    }

    const referenceIndex = buildReferenceIndex(allInstances)

    for (const [uuid, info] of outerBindingMap.entries()) {
        // Only nested tryCatch (branchIndex === -1) can produce an out-of-scope reference; a nested doInParallel is
        // prevented upstream by a diagnostic, so skip doInParallel branch bindings (branchIndex >= 0).
        if (info.branchIndex >= 0) {
            continue
        }

        const sources = referenceIndex.get(uuid)
        if (!sources) {
            continue
        }

        const bindingScopeUiId = bindingScopeOf(info)
        if (!bindingScopeUiId) {
            // Top-level tryCatch — its binding is reachable from anywhere; always representable.
            continue
        }

        for (const srcUiId of sources) {
            // Defensive; for a well-formed flow this never fires. Sources come only from `allInstances` (action /
            // subflow / flow-logic records), never the trigger — it isn't in `allInstances`, and running before any
            // action it cannot pill an action output — and every such record carries a `ui_id`. A missing `ui_id`
            // therefore means input we can't place in a scope, so fall back to Record() (which can represent any flow)
            // rather than risk an out-of-scope dot-walk. Cost is at worst a needless fallback, never broken output.
            if (srcUiId === undefined) {
                return true
            }

            const chain = ancestorChainMap.get(srcUiId)
            // Inside the target action's own branch/arm → the bare identifier is in scope; representable.
            if (chain?.has(info.branchUiId)) {
                continue
            }
            // Outside the branch AND the binding's `const` is not in scope at the source → unrepresentable.
            if (!chain?.has(bindingScopeUiId)) {
                return true
            }
        }
    }

    return false
}

/**
 * Build the catch-arm parameter map: try-arm action UUIDs that are referenced from inside their paired catch arm.
 *
 * Such a reference cannot use the bare identifier (the action's `const` lives in the *try* arrow, a different scope)
 * nor the outer `tryCatch_X` binding (referencing it from inside the catch arm would be a self-referential cycle the
 * build cannot resolve). Instead the catch arm receives the try arm's outputs as a parameter, and the reference
 * dot-walks through it: `tryOutputs.actionInstance_N`.
 *
 * Must be called after `buildUuidToIdentifierMap` so the module-level `uuidToRecordMap` is populated.
 *
 * @param ancestorChainMap - ui_id → ancestor chain (from `buildAncestorChainMap`).
 * @param allInstances - All flow instance records.
 * @returns Map of try-arm action UUID → catch-param info, for UUIDs actually referenced from the catch arm.
 */
export function buildCatchParamMap(
    ancestorChainMap: Map<string, Set<string>>,
    allInstances: ReadonlyArray<Record>
): Map<string, CatchParamInfo> {
    const result = new Map<string, CatchParamInfo>()
    const tryCatchLogicId = FLOW_LOGIC_SYS_ID_MAP[FLOW_LOGIC.TRY_CATCH]
    if (!tryCatchLogicId || allInstances.length === 0) {
        return result
    }

    // A record is "within" an arm when its ancestor chain contains that arm's ui_id.
    const isWithinArm = (recUiId: string | undefined, armUiId: string): boolean =>
        !!recUiId && (recUiId === armUiId || !!ancestorChainMap.get(recUiId)?.has(armUiId))

    for (const tryRec of allInstances) {
        if (tryRec.getTable() !== 'sys_hub_flow_logic_instance_v2') {
            continue
        }

        if (tryRec.get('logic_definition')?.ifString()?.getValue() !== tryCatchLogicId) {
            continue
        }

        const tryUiId = tryRec.get('ui_id')?.ifString()?.getValue()
        if (!tryUiId) {
            continue
        }

        const catchRec = allInstances.find(
            (r) =>
                r.getTable() === 'sys_hub_flow_logic_instance_v2' &&
                r.get('logic_definition')?.ifString()?.getValue() === TRY_CATCH_CATCH_SYS_ID &&
                r.get('connected_to')?.getValue() === tryUiId
        )

        const catchUiId = catchRec?.get('ui_id')?.ifString()?.getValue()
        if (!catchUiId) {
            continue
        }

        // Try-arm action/subflow UUIDs (anything in uuidToRecordMap whose owning record sits within the try arm).
        const tryArmUuids = [...uuidToRecordMap.entries()]
            .filter(([, rec]) => isWithinArm(rec.get('ui_id')?.ifString()?.getValue(), tryUiId))
            .map(([uuid]) => uuid)

        if (tryArmUuids.length === 0) {
            continue
        }

        // Records that live inside the catch arm — scan their compressed `values` for try-arm pills.
        const catchArmRecords = allInstances.filter((r) =>
            isWithinArm(r.get('ui_id')?.ifString()?.getValue(), catchUiId)
        )

        for (const catchInst of catchArmRecords) {
            const valuesStr = readValuesForPillScan(catchInst)
            if (!valuesStr) {
                continue
            }

            for (const uuid of tryArmUuids) {
                if (valuesStr.includes(`{{${uuid}.`) || valuesStr.includes(`{{step[${uuid}].`)) {
                    result.set(uuid, { paramName: CATCH_OUTPUTS_PARAM, catchArmUiId: catchUiId, tryUiId })
                }
            }
        }
    }

    return result
}

/**
 * Build a ui_id → ancestor-chain map for the given instances. Each entry's value is the set of all `ui_id`s in the
 * record's ancestor chain, including the record itself. Useful when resolving pills: a source record that lives
 * "inside the same branch" as the target action shares the target's branch `ui_id` in this set, and the bare
 * identifier can be used (no outer-binding dot-walk needed).
 */
export function buildAncestorChainMap(allInstances: ReadonlyArray<Record>): Map<string, Set<string>> {
    const recordByUiId = new Map<string, Record>()

    for (const inst of allInstances) {
        const ui = inst.get('ui_id')?.ifString()?.getValue()
        if (ui) {
            recordByUiId.set(ui, inst)
        }
    }

    const chainByUiId = new Map<string, Set<string>>()

    const computeChain = (uiId: string, seen: Set<string>): Set<string> => {
        const cached = chainByUiId.get(uiId)
        if (cached) {
            return cached
        }

        if (seen.has(uiId)) {
            return new Set([uiId]) // Cycle guard.
        }

        seen.add(uiId)

        const chain = new Set<string>([uiId])
        const rec = recordByUiId.get(uiId)
        const parent = rec?.get('parent_ui_id')?.ifString()?.getValue()
        if (parent) {
            for (const ancestor of computeChain(parent, seen)) {
                chain.add(ancestor)
            }
        }

        chainByUiId.set(uiId, chain)
        return chain
    }

    for (const inst of allInstances) {
        const ui = inst.get('ui_id')?.ifString()?.getValue()
        if (ui) {
            computeChain(ui, new Set())
        }
    }

    return chainByUiId
}

/**
 * Decide whether a pill referencing a target action should dot-walk through the outer scope binding.
 *
 * Returns `true` when the outer binding is required. The source record is outside the branch / arm that owns the
 * target action, and the bare identifier wouldn't be in scope. Returns `false` when source and target are in the same
 * branch (the bare identifier is already in scope).
 */
export function shouldUseOuterBinding(info: OuterBindingInfo, sourceAncestorUiIds: Set<string> | undefined): boolean {
    if (!sourceAncestorUiIds) {
        return true
    }

    return !sourceAncestorUiIds.has(info.branchUiId)
}

/**
 * Parse a flow-logic `order` into comparable numeric segments. Composite orders use the `➛` arrow separator to encode
 * an interstitial position (e.g. `16➛17` sits between 16 and 18). Each segment must be compared in turn; concatenating
 * the digits would mis-sort (`16➛17` → 1617, sorting after 18 instead of between 16 and 18).
 */
function parseOrder(record: Record): number[] {
    const raw = record.get('order')?.ifString()?.getValue() ?? '0'
    return raw.split(PARALLEL_ORDER_SEPARATOR).map((segment) => Number(segment) || 0)
}

/** Comparator for sibling flow-logic instances: compares `order` segment-by-segment (see `parseOrder`). */
function compareOrder(a: Record, b: Record): number {
    const segmentsA = parseOrder(a)
    const segmentsB = parseOrder(b)

    for (let i = 0; i < Math.max(segmentsA.length, segmentsB.length); i++) {
        const diff = (segmentsA[i] ?? 0) - (segmentsB[i] ?? 0)
        if (diff !== 0) {
            return diff
        }
    }
    return 0
}

/**
 * For each `doInParallel` / `tryCatch` block in `recordToShapeMap`, decide whether any inner action UUID is referenced
 * by a record outside the block. If not, unwrap the outer `VariableStatementShape` back to a bare
 * `CallExpressionShape` and strip the per-arm `return { ... }` from each branch arrow. The bare form matches the
 * pre-fix output and keeps diffs small for flows that don't need the new scoping.
 *
 * Mutates `recordToShapeMap` (replaces shapes for the affected records) and `outerBindingMap` (drops entries for
 * actions whose outer binding was stripped). Returns nothing.
 */
export function stripUnreferencedOuterBindings(
    recordToShapeMap: Map<Record, Shape>,
    outerBindingMap: Map<string, OuterBindingInfo>,
    ancestorChainMap: Map<string, Set<string>>,
    allInstances: ReadonlyArray<Record>
): void {
    if (outerBindingMap.size === 0) {
        return
    }

    // Group the affected block records by their outer-name owner. Each group corresponds to one `doInParallel` call
    // (whose outerNames are an array of `parallelBranch_X` per branch) or one `tryCatch` call (whose single outerName
    // is `tryCatch_X`).
    type BlockInfo = {
        blockRecord: Record
        // Interior ui_ids: everything inside the block (branch ui_ids + their descendants). A source record whose
        // `ui_id` is in this set is considered "inside" the block; if every reference to the block's inner actions
        // comes from inside, the outer binding can be stripped.
        //
        // Note (DEF0837398 limitation): "inside the block" is deliberately block-wide, not per-arm. A reference
        // from a sibling arm (e.g., a `tryCatch` catch arm referencing a try-arm action) is treated as an interior,
        // and the binding is stripped. Keeping the binding for that case would emit a self-referential
        // `const tryCatch_X = wfa.flowLogic.tryCatch(... catch references tryCatch_X ...)`, which the build-direction
        // identifier resolver cannot handle (it recurses into the const's own initializer forever). Cross-arm /
        // cross-branch output references therefore remain unsupported and need a non-self-referential representation;
        // see the cross-arm note in the PR description.
        interiorUiIds: Set<string>
        innerUuids: Set<string>
    }

    const blockByMainUiId = new Map<string, BlockInfo>()

    const recordByUiId = new Map<string, Record>()
    for (const inst of allInstances) {
        const ui = inst.get('ui_id')?.ifString()?.getValue()
        if (ui) {
            recordByUiId.set(ui, inst)
        }
    }

    // For each outer-binding entry, identify the *main* block record (parent of the branch/arm) and record the
    // inner UUID together with its owning branch/arm ui_id.
    for (const [uuid, info] of outerBindingMap.entries()) {
        const branchRecord = recordByUiId.get(info.branchUiId)
        if (!branchRecord) {
            continue
        }

        const logicDef = branchRecord.get('logic_definition')?.ifString()?.getValue()

        // Determine the main block ui_id depending on whether this is a parallel branch or a try/catch arm.
        let mainUiId: string | undefined
        if (logicDef === DO_IN_PARALLEL_BLOCK_SYS_ID) {
            mainUiId = branchRecord.get('parent_ui_id')?.ifString()?.getValue()
        } else if (logicDef === TRY_CATCH_CATCH_SYS_ID) {
            // Catch arm — pair points back to the try via `connected_to`. The try IS the main block.
            mainUiId = branchRecord.get('connected_to')?.ifString()?.getValue()
        } else {
            // Otherwise this is a try arm — branchRecord IS the main block.
            mainUiId = info.branchUiId
        }

        if (!mainUiId) {
            continue
        }

        let block = blockByMainUiId.get(mainUiId)
        if (!block) {
            const mainRec = recordByUiId.get(mainUiId)
            if (!mainRec) {
                continue
            }

            block = { blockRecord: mainRec, interiorUiIds: new Set(), innerUuids: new Set() }
            blockByMainUiId.set(mainUiId, block)
        }

        block.innerUuids.add(uuid)

        // Add every ui_id that descends from this branch / arm. The ancestor map's reverse use; a ui_id whose chain
        // contains `info.branchUiId` is a descendant of that branch.
        for (const [ui, chain] of ancestorChainMap.entries()) {
            if (chain.has(info.branchUiId)) {
                block.interiorUiIds.add(ui)
            }
        }
    }

    if (blockByMainUiId.size === 0) {
        return
    }

    // The set of action/subflow UUIDs referenced by ANY pill anywhere in the flow (incl. same-branch references such
    // as a `setFlowVariables` inside a doInParallel branch referencing that branch's own action). An inner action's
    // `const actionInstance_N` may only be stripped when its UUID is absent from this set — otherwise a surviving
    // reference would dangle.
    const referenceIndex = buildReferenceIndex(allInstances)
    const referencedAnywhere = new Set(referenceIndex.keys())

    // Decide, per block (keyed by its main record's sys_id), what to do with the outer binding:
    //   'strip'                  → no inner action escapes the block; unwrap to the bare CallExpression.
    //   { keep: Set<outerName> } → at least one inner action is referenced outside the block; keep the binding but
    //                              `_`-prefix / trim the outer names that are NOT referenced outside.
    // Keying by sys_id (not Shape identity) lets a SINGLE recursive pass apply the decision to the top-level
    // `recordToShapeMap` entry AND every embedded copy of the block nested inside another shape's arrow body — the
    // copies are distinct Shape instances produced by `recordToShape`, but they share the block's sys_id.
    type BlockDecision = 'strip' | { keep: Set<string> }
    const blockDecisions = new Map<string, BlockDecision>()

    for (const [mainUiId, block] of blockByMainUiId.entries()) {
        const sysId = block.blockRecord.getId().getValue()
        const referencedOutside = new Set<string>()

        // An inner UUID is referenced "outside" the block when any of its source `ui_id`s is neither interior to the
        // block nor the block's own main record. A source with no `ui_id` (undefined) is always outside, matching the
        // legacy per-instance scan.
        for (const uuid of block.innerUuids) {
            const sources = referenceIndex.get(uuid)
            if (!sources) {
                continue
            }

            for (const srcUiId of sources) {
                const isInterior = srcUiId !== undefined && block.interiorUiIds.has(srcUiId)
                if (!isInterior && srcUiId !== mainUiId) {
                    referencedOutside.add(uuid)
                    break
                }
            }
        }

        if (referencedOutside.size === 0) {
            // No inner action escapes the block; strip the outer binding entirely.
            blockDecisions.set(sysId, 'strip')
            for (const uuid of block.innerUuids) {
                outerBindingMap.delete(uuid)
            }

            continue
        }

        const keep = new Set<string>()
        for (const uuid of referencedOutside) {
            const info = outerBindingMap.get(uuid)
            if (info) {
                keep.add(info.outerName)
            }
        }
        blockDecisions.set(sysId, { keep })
    }

    if (blockDecisions.size === 0) {
        return
    }

    // Apply the decisions to every shape (top-level entries AND nested/embedded copies) in one recursive pass.
    for (const [rec, shape] of recordToShapeMap.entries()) {
        const replaced = applyBlockDecisions(shape, blockDecisions, referencedAnywhere)
        if (replaced !== shape) {
            recordToShapeMap.set(rec, replaced)
        }
    }
}

/**
 * Safety net: after datapill resolution, `_`-prefix any `doInParallel` outer destructured name that is not actually
 * referenced in the flow body. The strip pass keeps a name based on a `values`-scan heuristic that can over-keep in
 * deeply nested blocks; this pass corrects that by inspecting the *rendered* output.
 *
 * "Used" is determined textually: a name is used iff `name.` appears in the rendered body. This is reliable because
 * the destructuring declaration only ever writes a name as `[name` / `, name` / `name]` (never followed by a `.`),
 * while every reference is a property access `name.something`. Rendering the code is more robust than walking shape
 * subclasses, whose representation of a resolved condition pill varies. An unreferenced, unprefixed name would
 * otherwise trip `noUnusedLocals` (TS6133); over-prefixing a referenced name would trip TS2552.
 *
 * Known limitation: a `doInParallel` nested inside another flow-logic block (e.g., a `forEach` body) whose binding
 * names are unreferenced can still slip through and emit a few unprefixed unused names (cosmetic TS6133). The
 * common (top-level / referenced) cases are handled; the deeply nested-unused case is a tracked follow-up.
 *
 * Mutates `shapes` in place.
 */
export function pruneUnusedOuterBindingNames(shapes: Shape[]): void {
    let renderedBody: string
    try {
        renderedBody = shapes.map((s) => s.getCode()).join('\n')
    } catch {
        // If any shape can't be rendered yet, skip the safety net rather than risk a bad rename.
        return
    }
    const isUsed = (name: string): boolean => renderedBody.includes(`${name}.`)

    for (let i = 0; i < shapes.length; i++) {
        const shape = shapes[i]
        if (shape) {
            const replaced = prefixUnusedDoInParallelNames(shape, isUsed)
            if (replaced !== shape) {
                shapes[i] = replaced
            }
        }
    }
}

/**
 * `_`-prefix a `forEach` loop parameter (`item_N` → `_item_N`) when its body never references it, so TypeScript's
 * `noUnusedParameters` (TS6133) does not flag it. This matters beyond cosmetics: an unused `item_N` becomes an entry in
 * the SDK's *combined* `unusedIdentifier_delete` code fix, and that combined fix then also (incorrectly) sweeps in a
 * sibling output-binding `const` (`parallel_X` / a promoted container), unwrapping or deleting it and corrupting the
 * flow. Emitting the `_`-prefixed form means the flow has no unused identifiers for that combined fix to act on.
 *
 * Usage is determined textually from the body arrow's rendered code: the parameter is "used" iff its name appears as a
 * whole word more than once (once for the `(item_N) =>` declaration itself). Renaming is safe precisely because the
 * parameter is unreferenced. Mutates `shapes` in place.
 */
export function prefixUnusedForEachParams(shapes: Shape[]): void {
    for (let i = 0; i < shapes.length; i++) {
        const shape = shapes[i]
        if (shape) {
            const replaced = prefixForEachParamsInShape(shape)
            if (replaced !== shape) {
                shapes[i] = replaced
            }
        }
    }
}

/** Recursively rewrite `forEach` calls whose loop parameter is unused, `_`-prefixing that parameter. */
function prefixForEachParamsInShape(shape: Shape): Shape {
    let current = shape

    if (current instanceof CallExpressionShape && current.getCallee() === FLOW_LOGIC.FOR_EACH) {
        const args = current.getArguments()
        const body = args[2]
        if (body instanceof ArrowFunctionShape) {
            const params = body.getParameters()
            const param = params[0]
            const paramName = param?.getName()
            if (param && paramName && !paramName.startsWith('_') && !forEachParamIsUsed(body, paramName)) {
                const renamedBody = makeArrow(
                    {
                        source: body.getSource(),
                        parameters: [
                            new IdentifierShape({ source: param.getOriginalSource(), name: `_${paramName}` }),
                            ...params.slice(1),
                        ],
                        statements: body.getStatements(),
                    },
                    body.getReturnValue()
                )
                current = new CallExpressionShape({
                    source: current.getSource(),
                    callee: current.getCallee(),
                    args: [args[0], args[1], renamedBody],
                })
            }
        }
    }

    return recursePrefixForEachParams(current)
}

/** Whether a `forEach` body references its loop parameter — the name appears as a whole word beyond its declaration. */
function forEachParamIsUsed(body: ArrowFunctionShape, paramName: string): boolean {
    let code: string
    try {
        code = body.getCode()
    } catch {
        // If the body can't render yet, assume used (never rename away a possibly-referenced parameter).
        return true
    }
    const matches = code.match(new RegExp(`\\b${paramName}\\b`, 'g'))
    return (matches?.length ?? 0) > 1
}

/** Recurse the forEach-param pass into a shape's children (initializer, call args, arrow body, object props). */
function recursePrefixForEachParams(shape: Shape): Shape {
    if (shape instanceof VariableStatementShape) {
        const init = shape.getInitializer()
        const newInit = prefixForEachParamsInShape(init)
        return newInit === init ? shape : withInitializer(shape, newInit)
    }

    if (shape instanceof CallExpressionShape) {
        const args = shape.getArguments()
        let changed = false
        const newArgs = args.map((a) => {
            const r = prefixForEachParamsInShape(a)
            if (r !== a) {
                changed = true
            }
            return r
        })
        return changed
            ? new CallExpressionShape({ source: shape.getSource(), callee: shape.getCallee(), args: newArgs })
            : shape
    }

    if (shape instanceof ArrowFunctionShape) {
        const statements = shape.getStatements()
        let changed = false
        const newStatements = statements.map((s) => {
            const r = prefixForEachParamsInShape(s)
            if (r !== s) {
                changed = true
            }
            return r
        })
        if (!changed) {
            return shape
        }
        return makeArrow(
            { source: shape.getSource(), parameters: shape.getParameters(), statements: newStatements },
            shape.getReturnValue()
        )
    }

    if (shape instanceof ObjectShape) {
        let changed = false
        const properties: { [key: string]: Shape } = {}
        for (const [key, value] of shape.entries({ resolve: false })) {
            const r = prefixForEachParamsInShape(value)
            if (r !== value) {
                changed = true
            }
            properties[key] = r
        }
        return changed ? new ObjectShape({ source: shape.getSource(), properties }) : shape
    }

    return shape
}

/** Recursively `_`-prefix `doInParallel` single-binding names for which `isUsed(name)` is false. */
function prefixUnusedDoInParallelNames(shape: Shape, isUsed: (name: string) => boolean): Shape {
    let current = shape

    if (current instanceof VariableStatementShape && bindingCallee(current) === FLOW_LOGIC.DO_IN_PARALLEL) {
        const name = current.getVariableName().getName()
        if (!name.startsWith('_') && !isUsed(name)) {
            current = new VariableStatementShape({
                source: current.getSource(),
                variableName: new IdentifierShape({
                    source: current.getVariableName().getOriginalSource(),
                    name: `_${name}`,
                }),
                initializer: current.getInitializer(),
                isExported: current.isExported(),
            })
        }
    }

    // Recurse into children to handle nested doInParallel bindings.
    if (current instanceof VariableStatementShape) {
        const init = current.getInitializer()
        const newInit = prefixUnusedDoInParallelNames(init, isUsed)
        if (newInit !== init) {
            return withInitializer(current, newInit)
        }

        return current
    }
    if (current instanceof CallExpressionShape) {
        const args = current.getArguments()
        let changed = false
        const newArgs = args.map((a) => {
            const r = prefixUnusedDoInParallelNames(a, isUsed)
            if (r !== a) {
                changed = true
            }
            return r
        })
        return changed
            ? new CallExpressionShape({ source: current.getSource(), callee: current.getCallee(), args: newArgs })
            : current
    }
    if (current instanceof ArrowFunctionShape) {
        const statements = current.getStatements()
        let changed = false
        const newStatements = statements.map((s) => {
            const r = prefixUnusedDoInParallelNames(s, isUsed)
            if (r !== s) {
                changed = true
            }
            return r
        })
        if (!changed) {
            return current
        }
        return makeArrow(
            { source: current.getSource(), parameters: current.getParameters(), statements: newStatements },
            current.getReturnValue()
        )
    }
    if (current instanceof ObjectShape) {
        let changed = false
        const properties: { [key: string]: Shape } = {}
        for (const [k, v] of current.entries({ resolve: false })) {
            const r = prefixUnusedDoInParallelNames(v, isUsed)
            if (r !== v) {
                changed = true
            }
            properties[k] = r
        }
        return changed ? new ObjectShape({ source: current.getSource(), properties }) : current
    }

    return current
}

/**
 * Build a single reference index in one pass over every instance's decoded `values`: inner-action UUID → set of source
 * `ui_id`s that reference it via a `{{uuid.}}` / `{{step[uuid].}}` pill. A record with no `ui_id` contributes
 * `undefined` (such a source is always treated as "outside" any block, matching the legacy scan).
 *
 * `keys()` is the set of all referenced UUIDs (replaces the former `collectReferencedUuids` full pass), and the
 * per-source sets let `stripUnreferencedOuterBindings` decide outside-vs-inside without re-scanning every instance per
 * block.
 */
function buildReferenceIndex(allInstances: ReadonlyArray<Record>): Map<string, Set<string | undefined>> {
    const result = new Map<string, Set<string | undefined>>()
    const uuidRe = /\{\{(?:step\[)?([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/g
    for (const inst of allInstances) {
        const valuesStr = readValuesForPillScan(inst)
        if (!valuesStr) {
            continue
        }

        const sourceUiId = inst.get('ui_id')?.ifString()?.getValue()
        for (const m of valuesStr.matchAll(uuidRe)) {
            const uuid = m[1]
            if (!uuid) {
                continue
            }

            let sources = result.get(uuid)
            if (!sources) {
                sources = new Set<string | undefined>()
                result.set(uuid, sources)
            }

            sources.add(sourceUiId)
        }
    }
    return result
}

/**
 * Recursively apply per-block strip/keep decisions to a shape tree. For every `VariableStatementShape` wrapping a
 * `doInParallel`/`tryCatch` whose source record's sys_id has a decision:
 *   - 'strip'  → replace with the bare `CallExpressionShape` (drops the outer binding and synthetic returns).
 *   - { keep } → keep the binding but trim each arm's synthetic `return { … }` to names whose `const` survives
 *                (`doInParallel` via `renameUnusedDoInParallelName`, `tryCatch` via `trimKeptTryCatchArms`).
 * In both cases per-branch action `const`s whose UUID is not in `referencedAnywhere` are unwrapped to bare calls.
 * Recurses into the (possibly rewritten) node's children, so nested blocks at every depth are handled.
 */
function applyBlockDecisions(
    shape: Shape,
    decisions: Map<string, 'strip' | { keep: Set<string> }>,
    referencedAnywhere: Set<string>
): Shape {
    let current: Shape = shape

    if (current instanceof VariableStatementShape) {
        const init = current.getInitializer()
        if (
            init instanceof CallExpressionShape &&
            (init.getCallee() === FLOW_LOGIC.DO_IN_PARALLEL || init.getCallee() === FLOW_LOGIC.TRY_CATCH)
        ) {
            const src = current.getSource()
            const sysId = src instanceof Record ? src.getId().getValue() : undefined
            const decision = sysId ? decisions.get(sysId) : undefined

            if (decision === 'strip') {
                const bare = stripReturnsFromBlockShape(current, referencedAnywhere)
                if (bare) {
                    current = bare
                }
            } else if (decision && init.getCallee() === FLOW_LOGIC.DO_IN_PARALLEL) {
                current = renameUnusedDoInParallelName(current, init, decision.keep, referencedAnywhere)
            } else if (decision && init.getCallee() === FLOW_LOGIC.TRY_CATCH) {
                current = trimKeptTryCatchArms(current, init, referencedAnywhere)
            }
        }
    }

    return recurseApplyBlockDecisions(current, decisions, referencedAnywhere)
}

/** Recurse `applyBlockDecisions` into a shape's children (initializer, call args, arrow body, object props). */
function recurseApplyBlockDecisions(
    shape: Shape,
    decisions: Map<string, 'strip' | { keep: Set<string> }>,
    referencedAnywhere: Set<string>
): Shape {
    if (shape instanceof VariableStatementShape) {
        const init = shape.getInitializer()
        const newInit = applyBlockDecisions(init, decisions, referencedAnywhere)

        if (newInit === init) {
            return shape
        }

        return withInitializer(shape, newInit)
    }

    if (shape instanceof CallExpressionShape) {
        const args = shape.getArguments()
        let changed = false

        const newArgs = args.map((a) => {
            const r = applyBlockDecisions(a, decisions, referencedAnywhere)
            if (r !== a) {
                changed = true
            }
            return r
        })

        return changed
            ? new CallExpressionShape({ source: shape.getSource(), callee: shape.getCallee(), args: newArgs })
            : shape
    }

    if (shape instanceof ArrowFunctionShape) {
        const statements = shape.getStatements()
        let changed = false

        const newStatements = statements.map((s) => {
            const r = applyBlockDecisions(s, decisions, referencedAnywhere)
            if (r !== s) {
                changed = true
            }
            return r
        })

        if (!changed) {
            return shape
        }

        return makeArrow(
            { source: shape.getSource(), parameters: shape.getParameters(), statements: newStatements },
            shape.getReturnValue()
        )
    }

    if (shape instanceof ObjectShape) {
        let changed = false
        const properties: { [key: string]: Shape } = {}

        for (const [key, value] of shape.entries({ resolve: false })) {
            const r = applyBlockDecisions(value, decisions, referencedAnywhere)
            if (r !== value) {
                changed = true
            }

            properties[key] = r
        }

        return changed ? new ObjectShape({ source: shape.getSource(), properties }) : shape
    }

    return shape
}

/**
 * For a retained `doInParallel` single binding: clean each branch arrow (drop the synthetic return when the branch's
 * output is not consumed via the outer binding, and unwrap any action `const` whose UUID is not referenced anywhere).
 * The single outer name (`parallel_X`) is kept; individual branch outputs are accessed via `output_N`.
 */
function renameUnusedDoInParallelName(
    shape: VariableStatementShape,
    initializer: CallExpressionShape,
    keep: Set<string>,
    referencedAnywhere: Set<string>
): VariableStatementShape {
    const outerName = shape.getVariableName().getName()
    const args = initializer.getArguments()
    const branchArrows = args.slice(1)

    const newArrows = branchArrows.map((arrow) => {
        if (!(arrow instanceof ArrowFunctionShape)) {
            return arrow
        }

        // Keep the return for all branches when the outer binding is referenced.
        const dropReturn = !keep.has(outerName) && !outerName.startsWith('_')
        return cleanBranchArrow(arrow, referencedAnywhere, dropReturn)
    })

    const arrowsChanged = newArrows.some((a, i) => a !== branchArrows[i])
    if (!arrowsChanged) {
        return shape
    }

    const newCall = new CallExpressionShape({
        source: initializer.getSource(),
        callee: initializer.getCallee(),
        args: [args[0], ...newArrows],
    })

    return withInitializer(shape, newCall)
}

/**
 * Trim a kept `tryCatch` block's arm returns — the `tryCatch` counterpart of {@link renameUnusedDoInParallelName}. The
 * block binding (`const tryCatch_X = …`) is kept because an inner action is referenced from outside, but each arm's
 * synthetic `return { … }` is cleaned via {@link cleanBranchArrow} (with `dropReturn=false`) so it only names action
 * `const`s that survive: any arm action whose UUID isn't referenced anywhere is unwrapped to a bare call AND removed
 * from the arm's return. Without this, an unreferenced arm action (including any catch-arm action, since
 * `buildOutputsReturnShape` returns every arm action) would later be unwrapped by `unwrapUnreferencedActionBindings`
 * while its name lingered in the return, leaving the return naming an undeclared identifier.
 */
function trimKeptTryCatchArms(
    shape: VariableStatementShape,
    initializer: CallExpressionShape,
    referencedAnywhere: Set<string>
): VariableStatementShape {
    const arms = tryCatchArms(initializer)
    if (!arms) {
        return shape
    }

    const { configArg, handlersArg, tryArrow, catchArrow } = arms
    const newTry = cleanBranchArrow(tryArrow, referencedAnywhere, false)
    const newCatch = cleanBranchArrow(catchArrow, referencedAnywhere, false)

    if (newTry === tryArrow && newCatch === catchArrow) {
        return shape
    }

    const newHandlers = new ObjectShape({
        source: handlersArg.getSource(),
        properties: { try: newTry, catch: newCatch },
    })

    const newCall = new CallExpressionShape({
        source: initializer.getSource(),
        callee: initializer.getCallee(),
        args: [configArg, newHandlers],
    })

    return withInitializer(shape, newCall)
}

/**
 * Inject the catch-arm parameter for every `tryCatch` whose catch arm references a try-arm action.
 *
 * For each such block this rewrites the `tryCatch` call so that:
 * - the catch arrow declares the `tryOutputs` parameter (so `tryOutputs.actionInstance_N` resolves to a parameter,
 *   not a self-referential outer `const`), and
 * - the try arrow `return { ... }` includes every referenced output (re-added if the strip pass removed it), so the
 *   parameter actually carries those values.
 *
 * Runs after `stripUnreferencedOuterBindings`, independent of whether the block kept or dropped its outer binding —
 * the catch parameter is needed in both cases. Walks nested shapes so a `tryCatch` embedded inside another block's
 * arrow body is handled too.
 *
 * @param recordToShapeMap - Map of instance records to shapes (mutated in place).
 * @param catchParamMap - try-arm UUID → catch-param info (from `buildCatchParamMap`).
 * @param uuidToIdentifierMap - try-arm UUID → its `actionInstance_N` identifier (from `buildUuidToIdentifierMap`).
 */
export function applyCatchParamToShapes(
    recordToShapeMap: Map<Record, Shape>,
    catchParamMap: Map<string, CatchParamInfo>,
    uuidToIdentifierMap: Map<string, IdentifierShape>
): void {
    if (catchParamMap.size === 0) {
        return
    }

    // Group by tryUiId: the set of output identifier names the catch arm references, and the param name to use.
    const tryUiIdToKeep = new Map<string, { paramName: string; names: Set<string> }>()
    for (const [uuid, info] of catchParamMap.entries()) {
        const name = uuidToIdentifierMap.get(uuid)?.getName()
        if (!name) {
            continue
        }

        let entry = tryUiIdToKeep.get(info.tryUiId)
        if (!entry) {
            entry = { paramName: info.paramName, names: new Set() }
            tryUiIdToKeep.set(info.tryUiId, entry)
        }

        entry.names.add(name)
    }

    if (tryUiIdToKeep.size === 0) {
        return
    }

    for (const [rec, shape] of recordToShapeMap.entries()) {
        const replaced = injectCatchParamInShape(shape, tryUiIdToKeep)
        if (replaced !== shape) {
            recordToShapeMap.set(rec, replaced)
        }
    }
}

/** Recursively find `tryCatch` call expressions whose try record is in `tryUiIdToKeep` and inject the catch param. */
function injectCatchParamInShape(
    shape: Shape,
    tryUiIdToKeep: Map<string, { paramName: string; names: Set<string> }>
): Shape {
    if (shape instanceof CallExpressionShape) {
        if (shape.getCallee() === FLOW_LOGIC.TRY_CATCH) {
            const rewritten = injectCatchParamInTryCatch(shape, tryUiIdToKeep)
            if (rewritten) {
                return rewritten
            }
        }

        // Recurse into arguments (e.g., a doInParallel containing a tryCatch branch).
        const args = shape.getArguments()
        let changed = false

        const newArgs = args.map((a) => {
            const r = injectCatchParamInShape(a, tryUiIdToKeep)
            if (r !== a) {
                changed = true
            }
            return r
        })

        return changed
            ? new CallExpressionShape({ source: shape.getSource(), callee: shape.getCallee(), args: newArgs })
            : shape
    }

    if (shape instanceof VariableStatementShape) {
        const init = shape.getInitializer()
        const newInit = injectCatchParamInShape(init, tryUiIdToKeep)
        if (newInit === init) {
            return shape
        }

        return withInitializer(shape, newInit)
    }

    if (shape instanceof ArrowFunctionShape) {
        const statements = shape.getStatements()
        let changed = false

        const newStatements = statements.map((s) => {
            const r = injectCatchParamInShape(s, tryUiIdToKeep)
            if (r !== s) {
                changed = true
            }
            return r
        })

        if (!changed) {
            return shape
        }

        return makeArrow(
            { source: shape.getSource(), parameters: shape.getParameters(), statements: newStatements },
            shape.getReturnValue()
        )
    }

    if (shape instanceof ObjectShape) {
        let changed = false
        const properties: { [key: string]: Shape } = {}

        for (const [key, value] of shape.entries({ resolve: false })) {
            const r = injectCatchParamInShape(value, tryUiIdToKeep)
            if (r !== value) {
                changed = true
            }

            properties[key] = r
        }

        return changed ? new ObjectShape({ source: shape.getSource(), properties }) : shape
    }

    return shape
}

/**
 * Rewrite a single `wfa.flowLogic.tryCatch(config, { try, catch })` call: add the catch parameter and ensure the try
 * arm returns the referenced outputs. Returns `undefined` if this block has no catch-param references or the shape
 * doesn't match the expected structure.
 */
function injectCatchParamInTryCatch(
    callExpr: CallExpressionShape,
    tryUiIdToKeep: Map<string, { paramName: string; names: Set<string> }>
): CallExpressionShape | undefined {
    const src = callExpr.getSource()
    const tryUiId = src instanceof Record ? src.get('ui_id')?.ifString()?.getValue() : undefined
    if (!tryUiId) {
        return undefined
    }

    const keep = tryUiIdToKeep.get(tryUiId)
    if (!keep) {
        return undefined
    }

    const arms = tryCatchArms(callExpr)
    if (!arms) {
        return undefined
    }

    const { configArg, handlersArg, tryArrow, catchArrow } = arms

    // Ensure the try arrow returns the referenced outputs (merge with any existing return object).
    const mergedProps: { [key: string]: Shape } = {}
    const existingReturn = tryArrow.getReturnValue()
    if (existingReturn instanceof ObjectShape) {
        for (const [k, v] of existingReturn.entries({ resolve: false })) {
            mergedProps[k] = v
        }
    }

    for (const name of keep.names) {
        if (!mergedProps[name]) {
            mergedProps[name] = new IdentifierShape({ source: tryArrow.getSource(), name })
        }
    }

    const newTryArrow = new ArrowFunctionShape({
        source: tryArrow.getSource(),
        parameters: tryArrow.getParameters(),
        statements: tryArrow.getStatements(),
        returnValue: new ObjectShape({ source: tryArrow.getSource(), properties: mergedProps }),
    })

    // Ensure the catch arrow declares the `tryOutputs` parameter (no-op if already present).
    const catchParams = catchArrow.getParameters()
    const hasParam = catchParams.some((p) => p.getName() === keep.paramName)

    const newCatchArrow = makeArrow(
        {
            source: catchArrow.getSource(),
            parameters: hasParam
                ? catchParams
                : [new IdentifierShape({ source: catchArrow.getSource(), name: keep.paramName })],
            statements: catchArrow.getStatements(),
        },
        catchArrow.getReturnValue()
    )

    const newHandlers = new ObjectShape({
        source: handlersArg.getSource(),
        properties: { try: newTryArrow, catch: newCatchArrow },
    })

    return new CallExpressionShape({
        source: callExpr.getSource(),
        callee: callExpr.getCallee(),
        args: [configArg, newHandlers],
    })
}

/**
 * Given the `VariableStatementShape` wrapping a `wfa.flowLogic.doInParallel(...)` or `wfa.flowLogic.tryCatch(...)`
 * call, return the bare `CallExpressionShape` with every branch / arm arrow function rebuilt without its `returnValue`
 * (the synthetic `return { ... }` from `flow-logic-plugin`).
 *
 * Returns `undefined` if the shape doesn't match the expected structure.
 */
function stripReturnsFromBlockShape(
    wrapper: VariableStatementShape,
    referencedAnywhere: Set<string>
): CallExpressionShape | undefined {
    const callExpr = wrapper.getInitializer()
    if (!(callExpr instanceof CallExpressionShape)) {
        return undefined
    }

    const callee = callExpr.getCallee()
    const args = callExpr.getArguments()
    if (args.length === 0) {
        return undefined
    }

    if (callee === FLOW_LOGIC.DO_IN_PARALLEL) {
        const configArg = args[0]
        if (!configArg) {
            return undefined
        }

        const newBranchArrows: ArrowFunctionShape[] = []
        for (let i = 1; i < args.length; i++) {
            const arg = args[i]
            if (!(arg instanceof ArrowFunctionShape)) {
                return undefined
            }

            newBranchArrows.push(cleanBranchArrow(arg, referencedAnywhere, true))
        }

        return new CallExpressionShape({
            source: callExpr.getSource(),
            callee,
            args: [configArg, ...newBranchArrows],
        })
    }

    if (callee === FLOW_LOGIC.TRY_CATCH) {
        const arms = tryCatchArms(callExpr)
        if (!arms) {
            return undefined
        }

        const { configArg, handlersArg, tryArrow, catchArrow } = arms

        const newHandlers = new ObjectShape({
            source: handlersArg.getSource(),
            properties: {
                try: cleanBranchArrow(tryArrow, referencedAnywhere, true),
                catch: cleanBranchArrow(catchArrow, referencedAnywhere, true),
            },
        })

        return new CallExpressionShape({
            source: callExpr.getSource(),
            callee,
            args: [configArg, newHandlers],
        })
    }

    return undefined
}

/**
 * Clean a doInParallel branch / tryCatch arm arrow:
 *   - Unwrap each `const actionInstance_N = wfa.action(...)` to a bare call when `actionInstance_N`'s action UUID is
 *     not referenced by any pill anywhere (`referencedAnywhere`). Actions referenced somewhere — including a
 *     same-branch `setFlowVariables` or a downstream pill — keep their `const` so the reference still resolves.
 *   - When `dropReturn` is true, drop the arrow's synthetic `return { ... }` entirely (used when the branch's output
 *     is not consumed). Otherwise, keep the return but remove any entries whose `const` was just unwrapped.
 * Non-action statements (nested flow-logic, etc.) are left untouched.
 */
function cleanBranchArrow(
    arrow: ArrowFunctionShape,
    referencedAnywhere: Set<string>,
    dropReturn: boolean
): ArrowFunctionShape {
    const droppedNames = new Set<string>()
    let changed = false

    const newStatements = arrow.getStatements().map((s) => {
        if (s instanceof VariableStatementShape) {
            const init = s.getInitializer()

            if (init instanceof CallExpressionShape) {
                const callee = init.getCallee()

                if (callee === 'wfa.action' || callee === 'wfa.subflow') {
                    const uuid = actionUuidOf(init)
                    if (!uuid || !referencedAnywhere.has(uuid)) {
                        // Not referenced anywhere → safe to unwrap to a bare call.
                        droppedNames.add(s.getVariableName().getName())
                        changed = true
                        return init
                    }
                }
            }
        }

        return s
    })

    let newReturn = arrow.getReturnValue()
    if (newReturn instanceof ObjectShape) {
        if (dropReturn) {
            newReturn = undefined
            changed = true
        } else if (droppedNames.size > 0) {
            const remaining: { [key: string]: Shape } = {}

            for (const [k, v] of newReturn.entries({ resolve: false })) {
                if (!droppedNames.has(k)) {
                    remaining[k] = v
                }
            }

            newReturn =
                Object.keys(remaining).length === 0
                    ? undefined
                    : new ObjectShape({ source: newReturn.getSource(), properties: remaining })
            changed = true
        }
    }

    if (!changed) {
        return arrow
    }

    return makeArrow(
        { source: arrow.getSource(), parameters: arrow.getParameters(), statements: newStatements },
        newReturn
    )
}

/** Extract the `uuid` field from an action/subflow instance call's config object (arg 1). */
function actionUuidOf(actionCall: CallExpressionShape): string | undefined {
    return actionCall.getArgument(1)?.ifObject()?.get('uuid')?.ifString()?.getValue()
}

/** The set of every action/subflow UUID referenced by a pill anywhere in the flow (the reference index's keys). */
export function collectReferencedUuids(allInstances: ReadonlyArray<Record>): Set<string> {
    return new Set(buildReferenceIndex(allInstances).keys())
}

/**
 * Recursively unwrap `const actionInstance_N = wfa.action(...)` / `wfa.subflow(...)` bindings whose action UUID is not
 * referenced by any pill anywhere in the flow, rewriting them to bare call statements — at every depth, including
 * inside nested `if` / `forEach` / `doInParallel` / `tryCatch` bodies.
 *
 * Without this, an output-unreferenced action nested inside a block keeps its unused `const`, which the SDK's
 * unused-identifier cleanup (`fixUnusedCode` / `deleteUnusedCode`) must strip. That cleanup pre-computes the nodes for
 * a batch of unused declarations and then rewrites them one by one; rewriting one forgets the ts-morph nodes of the
 * others still queued, so with several nested unused `const`s it either deletes the action statement outright (the
 * step vanishes from the regenerated flow) or throws "Attempted to get information from a node that was removed or
 * forgotten". Emitting the bare call ourselves leaves nothing for that pass to strip, so nested actions survive.
 *
 * A referenced action (UUID in `referencedAnywhere`) keeps its `const` so pill dot-walks still resolve. Actions kept
 * alive by a surviving output-binding `return { name }` are always referenced-outside (the strip pass drops the return
 * otherwise), so they are in `referencedAnywhere` and are never unwrapped here.
 *
 * Mutates `shapes` in place.
 */
export function unwrapUnreferencedActionBindings(shapes: Shape[], referencedAnywhere: Set<string>): void {
    for (let i = 0; i < shapes.length; i++) {
        const shape = shapes[i]
        if (shape) {
            shapes[i] = unwrapUnreferencedActionsInShape(shape, referencedAnywhere)
        }
    }
}

/** True when `shape` is a non-exported `const x = wfa.action/subflow(...)` whose UUID is not in `referenced`. */
function isUnreferencedActionBinding(shape: Shape, referenced: Set<string>): shape is VariableStatementShape {
    if (!(shape instanceof VariableStatementShape) || shape.isExported()) {
        return false
    }

    const init = shape.getInitializer()
    if (!(init instanceof CallExpressionShape)) {
        return false
    }

    const callee = init.getCallee()
    if (callee !== 'wfa.action' && callee !== 'wfa.subflow') {
        return false
    }

    const uuid = actionUuidOf(init)
    return !uuid || !referenced.has(uuid)
}

/** Recursively apply {@link unwrapUnreferencedActionBindings} to a single shape, rewriting matches to their bare call. */
function unwrapUnreferencedActionsInShape(shape: Shape, referenced: Set<string>): Shape {
    if (isUnreferencedActionBinding(shape, referenced)) {
        // Drop the `const`; recurse into the bare call to stay uniform (its args won't hold nested action bindings).
        return recurseUnwrapUnreferencedActions(shape.getInitializer(), referenced)
    }

    return recurseUnwrapUnreferencedActions(shape, referenced)
}

/** Recurse the unwrap pass into a shape's children (initializer, call args, arrow body + return, object props). */
function recurseUnwrapUnreferencedActions(shape: Shape, referenced: Set<string>): Shape {
    if (shape instanceof VariableStatementShape) {
        const init = shape.getInitializer()
        const newInit = unwrapUnreferencedActionsInShape(init, referenced)
        return newInit === init ? shape : withInitializer(shape, newInit)
    }

    if (shape instanceof CallExpressionShape) {
        const args = shape.getArguments()
        let changed = false
        const newArgs = args.map((a) => {
            const r = unwrapUnreferencedActionsInShape(a, referenced)
            if (r !== a) {
                changed = true
            }
            return r
        })
        return changed
            ? new CallExpressionShape({ source: shape.getSource(), callee: shape.getCallee(), args: newArgs })
            : shape
    }

    if (shape instanceof ArrowFunctionShape) {
        const statements = shape.getStatements()
        let changed = false
        const newStatements = statements.map((s) => {
            const r = unwrapUnreferencedActionsInShape(s, referenced)
            if (r !== s) {
                changed = true
            }
            return r
        })
        if (!changed) {
            return shape
        }
        return makeArrow(
            { source: shape.getSource(), parameters: shape.getParameters(), statements: newStatements },
            shape.getReturnValue()
        )
    }

    if (shape instanceof ObjectShape) {
        let changed = false
        const properties: { [key: string]: Shape } = {}
        for (const [key, value] of shape.entries({ resolve: false })) {
            const r = unwrapUnreferencedActionsInShape(value, referenced)
            if (r !== value) {
                changed = true
            }
            properties[key] = r
        }
        return changed ? new ObjectShape({ source: shape.getSource(), properties }) : shape
    }

    return shape
}

/**
 * Read an instance record's `values` column for substring-search of datapill UUIDs. ServiceNow stores the values field
 * as a gzipped+base64 string. Returns the decompressed JSON-stringified payload, or `undefined` if the column is
 * missing / unreadable. Errors are swallowed because pill-scan failure is non-critical — the worst case is
 * over-keeping a binding.
 */
// Memoizes the decoded `values` column per record. Decoding gzips (via `gunzipSync`) which is expensive, and the same
// records are scanned repeatedly — once by `buildReferenceIndex`, once per catch arm in `buildCatchParamMap`, etc.
// Keyed by Record identity (WeakMap), so entries are collected once a flow's records go out of scope.
const valuesScanCache = new WeakMap<Record, string | undefined>()

function readValuesForPillScan(record: Record): string | undefined {
    const cached = valuesScanCache.get(record)
    if (cached !== undefined || valuesScanCache.has(record)) {
        return cached
    }

    const decoded = decodeValuesForPillScan(record)
    valuesScanCache.set(record, decoded)

    return decoded
}

function decodeValuesForPillScan(record: Record): string | undefined {
    const raw = record.get('values')?.getValue()
    if (raw === undefined || raw === null) {
        return undefined
    }

    if (typeof raw !== 'string') {
        // Already deserialized — stringify so callers can do substring search.
        try {
            return JSON.stringify(raw)
        } catch {
            return undefined
        }
    }

    if (raw === '') {
        return ''
    }

    // gzip magic bytes are `H4sI` when base64-encoded. `gunzipSync` (fflate) takes/returns a Uint8Array, so decode the
    // base64 to bytes on the way in and back to utf8 on the way out.
    if (raw.startsWith('H4sI')) {
        try {
            return Buffer.from(gunzipSync(Buffer.from(raw, 'base64'))).toString('utf8')
        } catch {
            return undefined
        }
    }

    return raw
}
