import type { FlowLogicInstanceShape } from './flow-logic-shapes'
import {
    ts,
    PropertyAccessShape,
    TemplateExpressionShape,
    IdentifierShape,
    ArrayShape,
    ObjectShape,
    CallExpressionShape,
    type Diagnostics,
    type Shape,
} from '@servicenow/sdk-build-core'
import { FLOW_LOGIC } from './flow-logic-constants'
import { DO_THE_FOLLOWING_UNTIL_CONDITION_API_NAME } from '../utils/flow-constants'
import { getCallExpressionName } from '../utils'
import { findAncestorByCalleeName } from '../utils/utils'
import {
    isDoInParallelShape,
    isDoTheFollowingShape,
    isSetFlowVariablesShape,
    isAppendToFlowVariablesShape,
    isAssignSubflowOutputsShape,
    isTryCatchShape,
} from './flow-logic-plugin-helpers'
import { ArrowFunctionShape } from '@servicenow/sdk-build-plugins'
import { PillShape } from '../utils/data-pill-shapes'
import { ARRAY_FLOW_DATA_TYPES, type ArrayFlowDataType } from '../../api'
import { FDInlineScriptCallShape } from '../plugins/inline-script-plugin'

type FlowLogicValidator = (expr: FlowLogicInstanceShape) => string | undefined

/** Emitted by validateDoTheFollowing when the loop body never sets an exit condition. */
export const DO_THE_FOLLOWING_UNTIL_MISSING_CONDITION_MESSAGE =
    'wfa.flowLogic.doTheFollowing body must call wfa.flowLogic.until(...); the loop has no exit condition without it.'

/** Emitted by validateDoTheFollowing when wfa.flowLogic.until(...) is not the last body statement. */
export const DO_THE_FOLLOWING_UNTIL_CONDITION_NOT_LAST_MESSAGE =
    'wfa.flowLogic.until(...) must be the last statement in the wfa.flowLogic.doTheFollowing body.'

/** Emitted when wfa.flowLogic.until(...) is called outside of a wfa.flowLogic.doTheFollowing body. */
export const DO_THE_FOLLOWING_UNTIL_OUTSIDE_BODY_MESSAGE =
    'wfa.flowLogic.until(...) can only be used inside a wfa.flowLogic.doTheFollowing body.'

const FLOW_LOGIC_VALIDATORS: { [K in FLOW_LOGIC]: FlowLogicValidator } = {
    [FLOW_LOGIC.GOBACKTO]: validateGoBackTo,
    [FLOW_LOGIC.IF]: validateIf,
    [FLOW_LOGIC.ELSEIF]: validateIf,
    [FLOW_LOGIC.ELSE]: validateIf,
    [FLOW_LOGIC.ENDFLOW]: validateEndFlow,
    [FLOW_LOGIC.EXITLOOP]: validateExitLoop,
    [FLOW_LOGIC.SKIP_ITERATION]: validateSkipIteration,
    [FLOW_LOGIC.WAIT_FOR_A_DURATION]: validateWaitForADuration,
    [FLOW_LOGIC.FOR_EACH]: validateForEach,
    [FLOW_LOGIC.DO_IN_PARALLEL]: validateDoInParallel,
    [FLOW_LOGIC.TRY_CATCH]: validateTryCatch,
    [FLOW_LOGIC.SET_FLOW_VARIABLES]: validateSetFlowVariables,
    [FLOW_LOGIC.APPEND_TO_FLOW_VARIABLES]: validateAppendToFlowVariables,
    [FLOW_LOGIC.ASSIGN_SUBFLOW_OUTPUTS]: validateAssignSubflowOutputs,
    [FLOW_LOGIC.DO_THE_FOLLOWING_UNTIL]: validateDoTheFollowing,
}

/**
 * Main validation function for flow logic instances.
 * Validates placement rules and context requirements for different flow logic types.
 *
 * @param expr - The flow logic instance shape to validate
 * @returns Error message if validation fails, undefined if valid
 */
export function validateFlowLogic(expr: FlowLogicInstanceShape, diagnostics: Diagnostics): string | undefined {
    const conditionType = expr.getCallee()
    const node = expr.getOriginalNode()
    const parent = node.getFirstAncestorByKind(ts.SyntaxKind.CallExpression)

    if (!parent) {
        return `'${conditionType}' can only be used inside a Flow() or Subflow() body`
    }
    const callExprName = getCallExpressionName(parent)

    const allowedCallExprNames = ['Flow', 'Subflow', ...Object.values(FLOW_LOGIC)]

    if (!allowedCallExprNames.includes(callExprName)) {
        return `'${conditionType}' can only be used inside a Flow() or Subflow() body`
    }

    // Validate sibling relationships for ElseIf/Else BEFORE running type-specific validators
    if (conditionType === FLOW_LOGIC.ELSEIF || conditionType === FLOW_LOGIC.ELSE) {
        const sibling = node
            .getParent()
            ?.getPreviousSibling((n) => !ts.Node.isCommentStatement(n))
            ?.asKind(ts.SyntaxKind.ExpressionStatement)
            ?.getExpression()
            .asKind(ts.SyntaxKind.CallExpression)

        const siblingError = validateSibling(expr, sibling)
        if (siblingError) {
            return siblingError
        }
    }

    const validator = FLOW_LOGIC_VALIDATORS[conditionType as FLOW_LOGIC]

    if (!validator) {
        diagnostics.error(expr, `Unsupported flow logic type for validation: ${conditionType}`)
        return
    }

    return validator(expr)
}

/**
 * Validates DoTheFollowing flow logic instance.
 *
 * Enforces the do-while loop contract: the call must take exactly 2 arguments (config, body).
 * The body is required — it is the only place the exit condition can live, since the
 * condition is set via a `wfa.flowLogic.until(...)` call inside the body — so a body-less call
 * is rejected here rather than left to crash later when the (missing) body is processed.
 *
 * @param expr - The DoTheFollowing flow logic instance shape to validate
 * @returns Error message if validation fails, undefined if valid
 */
function validateDoTheFollowing(expr: FlowLogicInstanceShape): string | undefined {
    const args = expr.getArguments()
    if (args.length !== 2) {
        return `wfa.flowLogic.doTheFollowing requires 2 arguments (config, body), but received ${args.length}`
    }

    if (isDoTheFollowingShape(expr) && !expr.getCondition()) {
        return DO_THE_FOLLOWING_UNTIL_MISSING_CONDITION_MESSAGE
    }

    // The exit condition must be the last statement in the body so it can reference all
    // action outputs declared earlier in the same iteration.
    if (isDoTheFollowingShape(expr)) {
        const body = expr.getBody()
        const statements = body.getStatements()
        const conditionIndex = statements.findIndex(
            (stmt) =>
                stmt instanceof CallExpressionShape && stmt.getCallee() === DO_THE_FOLLOWING_UNTIL_CONDITION_API_NAME
        )
        if (conditionIndex >= 0 && conditionIndex !== statements.length - 1) {
            return DO_THE_FOLLOWING_UNTIL_CONDITION_NOT_LAST_MESSAGE
        }
    }

    return undefined
}

function validateGoBackTo(expr: FlowLogicInstanceShape): string | undefined {
    const placementError = validateGoBackToPlacement(expr)
    if (placementError) {
        return placementError
    }
    return undefined
}

/**
 * Validates GoBackTo placement according to ServiceNow rules.
 *
 * Valid Go back to placement rules:
 * - The Go back to flow logic must be within a branch of a parent flow logic block:
 *   - Then branch of If, Else If, or Else flow logic
 *   - Catch branch of Try flow logic
 *   - Case branch of Decision flow logic
 * - The Go back to flow logic must be outside of the Error handler section
 *
 * @param expr - The GoBackTo flow logic instance shape
 * @returns Error message if placement is invalid, undefined if valid
 */
function validateGoBackToPlacement(expr: FlowLogicInstanceShape): string | undefined {
    const node = expr.getOriginalNode()

    // Check if GoBackTo is within a branch of a parent flow logic block
    const parentLogic = findParentFlowLogic(node)
    if (!parentLogic) {
        return 'GoBackTo must be within a branch of a parent flow logic block (If/Else/Decision/Try/Catch)'
    }

    // Check if GoBackTo is outside of Error handler section
    if (isWithinErrorHandler(node)) {
        return 'GoBackTo must be outside of the Error handler section'
    }

    return undefined
}

/**
 * Finds the nearest parent flow logic block (If/Else/Decision/Try/Catch/Parallel) in the AST.
 * Used to validate GoBackTo placement within proper flow logic branches.
 *
 * @param node - The AST node to start searching from
 * @returns The parent flow logic CallExpression, or undefined if not found
 */
function findParentFlowLogic(node: ts.Node | undefined): ts.CallExpression | undefined {
    const current = node?.getFirstAncestorByKind(ts.SyntaxKind.CallExpression)

    if (!current) {
        return undefined
    }

    const callName = getCallExpressionName(current)

    if ([FLOW_LOGIC.IF, FLOW_LOGIC.ELSEIF, FLOW_LOGIC.ELSE, FLOW_LOGIC.TRY_CATCH, 'MakeADecision'].includes(callName)) {
        if (callName === FLOW_LOGIC.TRY_CATCH) {
            // For TryCatch, GoBackTo should only be in the catch block, not in try block
            if (!isInCatchBlock(node)) {
                return undefined // Invalid placement - not in catch block
            }
        }

        return current
    }

    return undefined
}

/**
 * Checks if a node is within the catch block of a TryCatch flow logic.
 * GoBackTo is only allowed in the catch block, not in the try block.
 *
 * @param node - The AST node to check
 * @returns True if within catch block, false otherwise
 */
function isInCatchBlock(node: ts.Node | undefined): boolean {
    const current = node
        ?.getFirstAncestorByKind(ts.SyntaxKind.ArrowFunction)
        ?.getParentIfKind(ts.SyntaxKind.PropertyAssignment)
    if (current && current.getName() === 'catch') {
        return true
    }
    return false
}

/**
 * Checks if a node is within an Error handler section.
 * GoBackTo flow logic must be outside of Error handler sections per ServiceNow rules.
 *
 * @param node - The AST node to check
 * @returns True if within an Error handler, false otherwise
 */
function isWithinErrorHandler(_node: ts.Node | undefined): boolean {
    // TODO: Add implementation when Error handler is added in Flow
    return false
}

/**
 * Validates sibling relationships for conditional flow logic (If/Else/ElseIf).
 * Ensures proper chaining and structure of conditional blocks.
 *
 * @param expr - The flow logic instance shape
 * @param sibling - The sibling CallExpression to validate against
 * @returns Error message if sibling relationship is invalid, undefined if valid
 */
export function validateSibling(
    expr: FlowLogicInstanceShape,
    sibling: ts.CallExpression | undefined
): string | undefined {
    const conditionType = expr.getCallee()

    const isElseClause = conditionType === FLOW_LOGIC.ELSE
    const isElseIfClause = conditionType === FLOW_LOGIC.ELSEIF
    const siblingName = sibling ? getCallExpressionName(sibling) : undefined

    if (isElseClause || isElseIfClause) {
        if (!sibling) {
            return `${conditionType} clause must follow an If or ElseIf clause.`
        }

        const validPredecessors = [FLOW_LOGIC.IF, FLOW_LOGIC.ELSEIF]
        if (!validPredecessors.includes(siblingName as FLOW_LOGIC)) {
            return `${conditionType} clause must follow an If or ElseIf clause, but found ${siblingName}.`
        }
    }

    return undefined
}
function validateIf(expr: FlowLogicInstanceShape): string | undefined {
    const conditionType = expr.getCallee()

    // If and ElseIf require a condition parameter, Else does not
    if (conditionType === FLOW_LOGIC.IF || conditionType === FLOW_LOGIC.ELSEIF) {
        const config = expr.getConfig()
        const condition = config.get('condition')

        if (!condition || condition.isUndefined()) {
            return `${conditionType} requires a 'condition' field in the configuration object.`
        }
    }

    return undefined
}

function validateEndFlow(expr: FlowLogicInstanceShape): string | undefined {
    const placementError = validateEndFlowPlacement(expr)
    if (placementError) {
        return placementError
    }
    return undefined
}

function validateExitLoop(expr: FlowLogicInstanceShape): string | undefined {
    return validateLoopPlacement(expr, 'Exit Loop')
}

function validateSkipIteration(expr: FlowLogicInstanceShape): string | undefined {
    return validateLoopPlacement(expr, 'Skip Iteration')
}

function validateWaitForADuration(expr: FlowLogicInstanceShape): string | undefined {
    const args = expr.getArguments()

    if (args.length !== 1) {
        return `Expected 2 arguments for ${expr.getCallee()}, but received ${args.length}`
    }
    return undefined
}

function validateForEach(expr: FlowLogicInstanceShape): string | undefined {
    // Validate that forEach has the correct number of arguments
    const args = expr.getArguments()
    if (args.length < 2 || args.length > 3) {
        return `ForEach requires 2-3 arguments (items, config, optional body), but received ${args.length}`
    }

    // Validate config argument
    try {
        expr.getSysId()
    } catch (error) {
        return 'ForEach: Second argument (config) must be an object with valid $id property'
    }

    // Validate items argument (first argument) - must be an array type
    const itemsArg = expr.getArgument(0, false)
    if (!itemsArg || itemsArg.isUndefined()) {
        return 'ForEach: First argument (items) is required and cannot be undefined'
    }

    // Valid array types - imported from core package to ensure consistency

    // Helper to validate type hint
    const validateTypeHint = (typeHint: string): string | undefined => {
        if (!ARRAY_FLOW_DATA_TYPES.includes(typeHint as ArrayFlowDataType)) {
            return `ForEach requires an array type. The dataPill type '${typeHint}' is not an array type. Use array types like 'array.object', 'array.string', 'records', etc.`
        }
        return undefined
    }

    // Check if items is a PillShape (most common case - after DataPillPlugin transformation)
    if (itemsArg instanceof PillShape) {
        const typeHint = itemsArg.getType()
        if (typeHint) {
            const error = validateTypeHint(typeHint)
            if (error) {
                return error
            }
        }
    }

    // Check if items is a CallExpressionShape (before DataPillPlugin transformation)
    if (itemsArg instanceof CallExpressionShape) {
        const callee = itemsArg.getCallee()
        if (callee === 'wfa.dataPill') {
            const dataPillArgs = itemsArg.getArguments()
            if (dataPillArgs.length >= 2 && dataPillArgs[1]?.isString()) {
                const typeHint = dataPillArgs[1].asString().getValue()
                const error = validateTypeHint(typeHint)
                if (error) {
                    return error
                }
            }
        }
    }

    return undefined
}

// TypeScript enforces argument count, $id, and `() => void` shape of try/catch.
// The plugin's transform logic requires arrow functions specifically, which TS does not distinguish from other
// function forms — so check that here.
function validateTryCatch(expr: FlowLogicInstanceShape): string | undefined {
    if (!isTryCatchShape(expr)) {
        return undefined
    }

    const handlers = expr.getArgument(1)?.if(ObjectShape)
    const tryHandler = handlers?.get('try')
    const catchHandler = handlers?.get('catch')

    if (!tryHandler?.if(ArrowFunctionShape)) {
        return "TryCatch: 'try' handler must be an arrow function"
    }

    if (!catchHandler?.if(ArrowFunctionShape)) {
        return "TryCatch: 'catch' handler must be an arrow function"
    }

    return undefined
}

function validateDoInParallel(expr: FlowLogicInstanceShape): string | undefined {
    if (isDoInParallelShape(expr)) {
        // Check for nested `DoInParallel`. `findAncestorByCalleeName` returns the node itself when it matches, so
        // start the search from the parent call expression. Otherwise, every `DoInParallel` would flag itself.
        const parentCall = expr.getOriginalNode()?.getFirstAncestorByKind(ts.SyntaxKind.CallExpression)
        const parentDoInParallel = findAncestorByCalleeName(parentCall, FLOW_LOGIC.DO_IN_PARALLEL)

        if (parentDoInParallel) {
            return 'Nested DoInParallel calls are not allowed. DoInParallel cannot be used within another DoInParallel block.'
        }
    }

    return undefined
}

/**
 * Shared validator for "variable assignment"-style flow logic shapes (SetFlowVariables and AppendToFlowVariables).
 * Both shapes share the (config, schema, values) argument layout and the same value-type rules; only the type guard,
 * the values' accessor, and the error-message prefix differ. Routing both through one helper prevents the two
 * implementations from drifting independently and ensures any future validation change applies to both call sites at
 * once.
 *
 * Validations performed:
 *   1. Argument count must be exactly 3 (config, schema, values).
 *   2. Config must expose a valid $id (`expr.getSysId()` must not throw).
 *   3. Values argument must be a defined, non-empty object.
 *   4. Every key must be a non-empty string.
 *   5. Every value must be a string / number / boolean / object / array / datapill / inline script.
 *
 * @param expr     - The flow logic instance shape to validate.
 * @param name     - API name used as the error-message prefix (e.g., 'SetFlowVariables').
 * @param isShape  - Type-guard distinguishing the specific assignment shape.
 * @param getValues - Accessor returning the values ObjectShape from the narrowed shape.
 * @returns Error message if validation fails, undefined otherwise.
 */
function validateVariableAssignmentShape<S extends FlowLogicInstanceShape>(
    expr: FlowLogicInstanceShape,
    name: string,
    isShape: (e: FlowLogicInstanceShape) => e is S,
    getValues: (shape: S) => ObjectShape | undefined
): string | undefined {
    if (!isShape(expr)) {
        return undefined
    }

    const args = expr.getArguments()
    if (args.length !== 3) {
        return `${name} requires exactly 3 arguments (config, schema, values), but received ${args.length}`
    }

    try {
        expr.getSysId()
    } catch {
        return `${name}: First argument (config) must be an object with valid $id property`
    }

    const valuesArg = getValues(expr)
    if (!valuesArg || valuesArg.isUndefined()) {
        return `${name}: Third argument (values) is required`
    }

    if (!valuesArg.isObject()) {
        return `${name}: Third argument (values) must be an object`
    }

    const entries = Array.from(valuesArg.entries({ resolve: false }))
    if (entries.length === 0) {
        return `${name}: Values object cannot be empty - at least one variable is required`
    }

    for (const [key, valueShape] of entries) {
        if (!key || key.trim() === '') {
            return `${name}: Variable names cannot be empty`
        }

        if (valueShape.isUndefined()) {
            return `${name}: Variable '${key}' has undefined value`
        }

        const isDatapill = valueShape instanceof PropertyAccessShape || valueShape instanceof TemplateExpressionShape
        const isInlineScript = valueShape instanceof FDInlineScriptCallShape
        const isIdentifier = valueShape instanceof IdentifierShape
        const isArrayOrObject = valueShape instanceof ArrayShape || valueShape instanceof ObjectShape
        const isValidType =
            valueShape.isString() ||
            valueShape.isNumber() ||
            valueShape.isBoolean() ||
            isDatapill ||
            isArrayOrObject ||
            isInlineScript

        if (!isValidType) {
            if (isIdentifier) {
                return `${name}: Variable '${key}' cannot use local variable references. Use direct values (literals) or datapills (e.g., params.someField) instead`
            }

            return `${name}: Variable '${key}' has invalid value type. Expected string, number, boolean, object, array, or datapill expression`
        }
    }

    return undefined
}

function validateSetFlowVariables(expr: FlowLogicInstanceShape): string | undefined {
    return validateVariableAssignmentShape(expr, 'SetFlowVariables', isSetFlowVariablesShape, (s) =>
        s.getVariablesToSet()
    )
}

/**
 * Validates AppendToFlowVariables flow logic instance.
 *
 * The "target must be array-typed" constraint is enforced at compile time by the API type signature
 * (`KV[K] extends Array<infer E> ? ... : never`). The platform only supports appending to Array.Object flow variables —
 * other array element types (string / integer / boolean / datetime) are runtime no-ops, so this validator emits an
 * error for any target whose flow variable is not declared as `FlowArray({ elementType: FlowObject(...) })`. The
 * remaining argument / structural checks are shared with SetFlowVariables via `validateVariableAssignmentShape`.
 *
 * Additionally, when an array literal is provided as the value for an Array.Object target, every element must itself
 * be an object literal or a datapill expression — primitive literals are not valid array.object elements and the TS
 * `unknown[]` arm of the value union lets them slip past the compile-time check.
 *
 * @param expr - The AppendToFlowVariables flow logic instance shape
 * @returns Error message if validation fails, undefined if valid
 */
function validateAppendToFlowVariables(expr: FlowLogicInstanceShape): string | undefined {
    const shapeError = validateVariableAssignmentShape(
        expr,
        'AppendToFlowVariables',
        isAppendToFlowVariablesShape,
        (s) => s.getValuesToAppend()
    )
    if (shapeError) {
        return shapeError
    }

    if (!isAppendToFlowVariablesShape(expr)) {
        return undefined
    }

    const parentFlow = findAncestorByCalleeName(expr.getOriginalNode(), 'Flow', 'Subflow')
    if (!parentFlow) {
        // Placement is already validated by the umbrella check; nothing further to assert here.
        return undefined
    }

    const flowVariableInitializers = getFlowVariableInitializers(parentFlow)
    const valuesArg = expr.getValuesToAppend()
    for (const [key, valueShape] of valuesArg.entries({ resolve: false })) {
        const initializer = flowVariableInitializers.get(key)
        // If the variable isn't declared in flowVariables, the TS signature has already rejected the key at compile
        // time — skip rather than double-reporting.
        if (!initializer) {
            continue
        }
        if (!isArrayObjectFlowVariable(initializer)) {
            return `AppendToFlowVariables: Variable '${key}' is not an Array.Object flow variable. AppendToFlowVariables only supports Array.Object targets — declare the variable as FlowArray({ elementType: FlowObject(...) }).`
        }
        const elementError = validateArrayObjectElements(key, valueShape)
        if (elementError) {
            return elementError
        }
    }

    return undefined
}

/**
 * For an Array.Object target, every element of an array-literal value must be an object literal or a datapill
 * expression. A primitive literal (string / number / boolean) inside the array is silently accepted by TypeScript
 * (via the `unknown[]` arm of the value union) but rejected by the platform at runtime, so we flag it here.
 *
 * Non-array values (single object literal, whole-field template string, whole-field datapill) are accepted as-is —
 * those arms are already covered by the shared `validateVariableAssignmentShape` checks and by the platform's own
 * runtime handling.
 */
function validateArrayObjectElements(key: string, valueShape: Shape): string | undefined {
    if (!valueShape.isArray()) {
        return undefined
    }

    const elements = valueShape.asArray().getElements(false)
    for (const [i, element] of elements.entries()) {
        if (isArrayObjectElement(element)) {
            continue
        }

        return `AppendToFlowVariables: Variable '${key}' has an invalid element at index ${i}. Array.Object variables only accept object literals or datapill expressions as elements — primitive values are not allowed.`
    }

    return undefined
}

function isArrayObjectElement(element: Shape): boolean {
    if (element instanceof ObjectShape) {
        return true
    }
    if (
        element instanceof PropertyAccessShape ||
        element instanceof TemplateExpressionShape ||
        element instanceof PillShape ||
        element instanceof FDInlineScriptCallShape
    ) {
        return true
    }

    // `wfa.dataPill(...)` calls are unwrapped to PillShape by the DataPillPlugin in normal builds. However, raw
    // CallExpressionShape can still arrive here for fixtures that haven't been subclassed yet — accept any call
    // expression whose callee resolves to wfa.dataPill so the order of plugin subclassing does not matter.
    return element instanceof CallExpressionShape && element.getCallee() === 'wfa.dataPill'
}

/**
 * Reads a Flow / Subflow's `flowVariables` config property and returns a map from variable name to its initializer
 * expression. Returns an empty map when `flowVariables` is missing or shaped unexpectedly — those cases are handled by
 * other validators (or by the TypeScript type system) and should not be re-flagged here.
 */
function getFlowVariableInitializers(flowOrSubflow: ts.CallExpression): Map<string, ts.Expression> {
    const result = new Map<string, ts.Expression>()
    const configArg = flowOrSubflow.getArguments()[0]
    if (!configArg || !ts.Node.isObjectLiteralExpression(configArg)) {
        return result
    }
    const flowVarsProp = configArg.getProperty('flowVariables')?.asKind(ts.SyntaxKind.PropertyAssignment)
    const flowVarsObject = flowVarsProp?.getInitializer()?.asKind(ts.SyntaxKind.ObjectLiteralExpression)
    if (!flowVarsObject) {
        return result
    }
    for (const prop of flowVarsObject.getProperties()) {
        const propertyAssignment = prop.asKind(ts.SyntaxKind.PropertyAssignment)
        const initializer = propertyAssignment?.getInitializer()
        if (!propertyAssignment || !initializer) {
            continue
        }
        result.set(getPropertyAssignmentName(propertyAssignment), initializer)
    }
    return result
}

function getPropertyAssignmentName(node: ts.PropertyAssignment): string {
    const nameNode = node.getNameNode()
    return ts.Node.isStringLiteral(nameNode) || ts.Node.isNoSubstitutionTemplateLiteral(nameNode)
        ? nameNode.getLiteralValue()
        : nameNode.getText()
}

/**
 * Returns true when the given flow-variable initializer expression is a `FlowArray({ elementType: FlowObject(...) })`
 * call — the only flow-variable shape that AppendToFlowVariables can target at runtime.
 */
function isArrayObjectFlowVariable(initializer: ts.Expression): boolean {
    if (!ts.Node.isCallExpression(initializer) || getCallExpressionName(initializer) !== 'FlowArray') {
        return false
    }
    const flowArrayConfig = initializer.getArguments()[0]?.asKind(ts.SyntaxKind.ObjectLiteralExpression)
    const elementTypeProp = flowArrayConfig?.getProperty('elementType')?.asKind(ts.SyntaxKind.PropertyAssignment)
    const elementTypeInit = elementTypeProp?.getInitializer()
    if (!elementTypeInit || !ts.Node.isCallExpression(elementTypeInit)) {
        return false
    }
    return getCallExpressionName(elementTypeInit) === 'FlowObject'
}

/**
 * Validates AssignSubflowOutputs flow logic instance.
 * Performs comprehensive validation of arguments, types, structure, and placement.
 *
 * **Validations performed:**
 * 1. Placement: Must be within a Subflow() definition (not in regular Flow)
 * 2. Argument count: Must have exactly 3 arguments
 * 3. Config object: Must contain required $id property
 * 4. Schema argument: Must be params.outputs (schema reference)
 * 5. Values object: Must be non-empty
 * 6. Output names: Cannot be empty or whitespace
 * 7. Output values: Must be valid types (string, number, boolean, or datapill)
 *
 * **Valid value types:**
 * - String literals: "success"
 * - Numbers: 42, 3.14
 * - Booleans: true, false
 * - Objects: { a: "value", b: 42 } (ObjectShape - for FlowObject types)
 * - Arrays: [1, 2, 3] (ArrayShape - for FlowArray types)
 * - Datapills: params.action.result, params.complexObject (PropertyAccessShape)
 * - Template expressions: `Result: ${params.action.result}` (TemplateExpressionShape)
 *
 * **Important:** AssignSubflowOutputs can ONLY be used within a Subflow() definition.
 * Using it in a regular Flow will result in a validation error.
 *
 * @param expr - The AssignSubflowOutputs flow logic instance shape
 * @returns Error message if validation fails, undefined if valid
 *
 * @example
 * // Valid usage (within Subflow)
 * Subflow({
 *   outputs: { result: StringColumn(...) }
 * }, (params) => {
 *   wfa.flowLogic.assignSubflowOutputs(
 *     { $id: Now.ID['...'] },
 *     params.outputs,  // ← Schema reference (2nd argument)
 *     { result: params.action.data, status: "complete" }
 *   )
 * })
 */
function validateAssignSubflowOutputs(expr: FlowLogicInstanceShape): string | undefined {
    if (!isAssignSubflowOutputsShape(expr)) {
        return undefined
    }

    // Validate that this is called within a Subflow() definition
    const node = expr.getOriginalNode()
    const subflowAncestor = findAncestorByCalleeName(node, 'Subflow')
    if (!subflowAncestor) {
        return 'AssignSubflowOutputs can only be used within a Subflow'
    }

    // Validate argument count
    const args = expr.getArguments()
    if (args.length !== 3) {
        return `AssignSubflowOutputs requires exactly 3 arguments (config, schema, values), but received ${args.length}`
    }

    // Validate config argument
    try {
        expr.getSysId()
    } catch (error) {
        return 'AssignSubflowOutputs: First argument (config) must be an object with valid $id property'
    }

    // Validate values argument (third argument)
    const valuesArg = expr.getAssignedSubflowOutputs()
    if (!valuesArg || valuesArg.isUndefined()) {
        return 'AssignSubflowOutputs: Third argument (values) is required'
    }

    if (!valuesArg.isObject()) {
        return 'AssignSubflowOutputs: Third argument (values) must be an object'
    }

    // Validate that values object is not empty
    const entries = Array.from(valuesArg.entries({ resolve: false }))
    if (entries.length === 0) {
        return 'AssignSubflowOutputs: Values object cannot be empty - at least one output must be assigned'
    }

    // Validate each value in the object
    for (const [key, valueShape] of entries) {
        if (!key || key.trim() === '') {
            return 'AssignSubflowOutputs: Output names cannot be empty'
        }

        // Check if value is valid (string, datapill, template expression, or inline script)
        if (valueShape.isUndefined()) {
            return `AssignSubflowOutputs: Output '${key}' has undefined value`
        }

        // Values can be: strings, numbers, booleans, objects, arrays, datapills, template expressions, or inline scripts
        const isDatapill = valueShape instanceof PropertyAccessShape || valueShape instanceof TemplateExpressionShape
        const isInlineScript = valueShape instanceof FDInlineScriptCallShape
        const isIdentifier = valueShape instanceof IdentifierShape
        const isArrayOrObject = valueShape instanceof ArrayShape || valueShape instanceof ObjectShape
        const isValidType =
            valueShape.isString() ||
            valueShape.isNumber() ||
            valueShape.isBoolean() ||
            isDatapill ||
            isArrayOrObject ||
            isInlineScript

        if (!isValidType) {
            // Provide specific error message for unsupported types
            if (isIdentifier) {
                return `AssignSubflowOutputs: Output '${key}' cannot use local variable references. Use direct values (literals) or datapills (e.g., params.someField) instead`
            }
            return `AssignSubflowOutputs: Output '${key}' has invalid value type. Expected string, number, boolean, object, array, or datapill expression`
        }
    }

    return undefined
}

/**
 * Validates that a loop control flow logic (Exit Loop or Skip Iteration) is within a valid loop construct.
 *
 * @param expr - The flow logic instance shape to validate
 * @param logicName - The name of the logic for error messages (e.g., 'Exit Loop', 'Skip Iteration')
 * @returns Error message if placement is invalid, undefined if valid
 */
function validateLoopPlacement(expr: FlowLogicInstanceShape, logicName: string): string | undefined {
    const node = expr.getOriginalNode()

    // Loop constructs that loop control flow logic can be used within
    const LOOP_CONSTRUCTS = [FLOW_LOGIC.FOR_EACH, FLOW_LOGIC.DO_THE_FOLLOWING_UNTIL]

    const parentLoop = findAncestorByCalleeName(node, ...LOOP_CONSTRUCTS)
    if (!parentLoop) {
        return `${logicName} must be used within a Do The Following or For Each loop`
    }

    return undefined
}

function validateEndFlowPlacement(expr: FlowLogicInstanceShape): string | undefined {
    const node = expr.getOriginalNode()

    // Block constructs that End Flow can be used within
    const END_FLOW_BLOCKS = [
        FLOW_LOGIC.FOR_EACH,
        FLOW_LOGIC.IF,
        FLOW_LOGIC.ELSEIF,
        FLOW_LOGIC.ELSE,
        FLOW_LOGIC.DO_IN_PARALLEL,
        FLOW_LOGIC.DO_THE_FOLLOWING_UNTIL,
        FLOW_LOGIC.TRY_CATCH,
    ]

    const parentBlock = findAncestorByCalleeName(node, ...END_FLOW_BLOCKS)
    if (!parentBlock) {
        return 'End Flow must be used within a Do In Parallel, Do The Following, For Each, Try/Catch, or If block'
    }

    return undefined
}
