import type { Column } from '@servicenow/sdk-core/db'
import type { FlowIOType, FlowValueType, OutputsWithDependentTable, ExtractDependentField } from './FlowTypes'
import type { TableName } from '@servicenow/sdk-core/db'

/**
 * Configuration for a step definition
 */
export type StepDefinitionConfig<
    I extends Record<string, FlowValueType>,
    O extends Record<string, FlowValueType>,
> = Now.Internal.WithIdAndMetadata<{
    name: string
    shortDescription?: string
    category?: string
    inputs?: I
    outputs?: O
    /** Whether this step allows extended inputs */
    allowExtendedInputs?: boolean
    /** Whether this step allows extended outputs */
    allowExtendedOutputs?: boolean
}>

/**
 * Basic callable step interface
 */
export interface ActionStep<I, O> {
    (id: string | Now.Internal.ExplicitKey, config: I): void
    output: O
}

/**
 * Extended ActionStep that carries the two flags as type-level booleans.
 * AI/AO are literal booleans (true/false) and are used later for conditional typing.
 */
export interface ActionStepWithMeta<I, O, AI extends boolean, AO extends boolean> extends ActionStep<I, O> {
    /** Carry compile-time flags. Optional to match typical config shapes. */
    allowExtendedInputs?: AI | undefined
    allowExtendedOutputs?: AO | undefined
}

/**
 * StepDefinition: returns an ActionStepWithMeta that preserves the allow_* flags at the type level.
 * - AI / AO are inferred from the provided config when you pass literal true/false values.
 */
export function ActionStepDefinition<
    I extends Record<string, FlowValueType>,
    O extends Record<string, FlowValueType>,
    AI extends boolean = false,
    AO extends boolean = false,
>(
    _config: StepDefinitionConfig<I, O> & {
        /** Make TypeScript infer the literal booleans when provided */
        allowExtendedInputs?: AI | undefined
        allowExtendedOutputs?: AO | undefined
    }
): ActionStepWithMeta<FlowIOType<I>, FlowIOType<O>, AI, AO> {
    // runtime: no-op; types are what matters
    return undefined as unknown as ActionStepWithMeta<FlowIOType<I>, FlowIOType<O>, AI, AO>
}

export interface ExtendedInputConfigItem {
    label: string
    value: unknown
}

export type ExtendedInputConfig = Record<string, ExtendedInputConfigItem>

type ActionStepInstanceConfig = Now.Internal.WithIdAndMetadata<{
    label?: string
}>

/**
 * Conditional helper types
 * When AI is true, allow inputVariables as an object; otherwise forbid it (never).
 * When AO is true, allow outputVariables; otherwise forbid it (never).
 */
type InputVarsFor<AI extends boolean> = AI extends true
    ? { inputVariables?: ExtendedInputConfig }
    : { inputVariables?: never }

/**
 * Helper type to extract output variable names and types from output_variables object
 * Converts { outputVariable_1: StringColumn({...}), outputVariable_2: IntegerColumn({...}) } to { outputVariable_1: string, outputVariable_2: number }
 */
/**
 * Find the dependent field name from outputs (e.g., 'table_name' from DocumentIdColumn({dependent: 'table_name'}))
 */
type FindStepDependentField<O> =
    O extends Record<string, FlowValueType> ? { [K in keyof O]: ExtractDependentField<O[K]> }[keyof O] : never

/**
 * Extract the table name from step inputs using the dependent field name.
 */
type ExtractStepTable<TInputs, O> =
    FindStepDependentField<O> extends string
        ? FindStepDependentField<O> extends keyof TInputs
            ? TInputs[FindStepDependentField<O>] extends TableName
                ? TInputs[FindStepDependentField<O>]
                : never
            : never
        : never

/**
 * Resolve step outputs with table-aware dot-walk.
 * - When table schema is available: full IntelliSense for table fields (e.g., incident.short_description)
 * - When table schema is NOT available: returns `any` for unrestricted dot-walk (same as Action())
 * - When no dependent outputs: returns typed outputs with IntelliSense for output names
 */
type StepOutputs<O, TInputs> = [O] extends [any]
    ? any
    : O extends Record<string, FlowValueType>
      ? ExtractStepTable<TInputs, O> extends never
          ? Required<FlowIOType<O>>
          : OutputsWithDependentTable<O, ExtractStepTable<TInputs, O>>
      : any

/**
 * ActionStep overload: Fallback for step references passed as a string (sys_id or name).
 * Used when the step definition can't be resolved to a typed ActionStepDefinition —
 * e.g., built-in steps or customer-defined steps whose definition isn't in the current project.
 * Returns `any` to allow arbitrary property access for untyped step references.
 */
export function ActionStep(
    _step: string,
    _config: ActionStepInstanceConfig,
    _inputs: Record<string, unknown> & { errorHandlingType?: 'stop_the_action' | 'dont_stop_the_action' }
): any
/**
 * ActionStep overload: Custom step type referenced by ActionStepDefinition.
 * Returns typed outputs with IntelliSense for output names and table-aware dot-walk.
 */
export function ActionStep<
    I extends Record<string, any>,
    O extends Record<string, any>,
    AI extends boolean,
    AO extends boolean,
    TInputs extends FlowIOType<I>,
    const OutputVars extends Record<string, Column>,
>(
    _step: ActionStepWithMeta<FlowIOType<I>, FlowIOType<O>, AI, AO>,
    _config: ActionStepInstanceConfig,
    _inputs: TInputs & { errorHandlingType?: 'stop_the_action' | 'dont_stop_the_action' } & InputVarsFor<AI> &
        (AO extends true ? { outputVariables?: OutputVars } : { outputVariables?: never })
): StepOutputs<O, TInputs>

export function ActionStep(_step: unknown, _config: ActionStepInstanceConfig, _inputs: unknown): unknown {
    return undefined as unknown
}
