import type { Column, TableName } from '@servicenow/sdk-core/db'
import type { FlowIOType, FlowValueType, TableAwareRecordWithFallback, OutputsWithDotwalk } from './FlowTypes'

type TriggerType =
    | 'analytics'
    | 'run_once'
    | 'monthly'
    | 'rest'
    | 'email'
    | 'remote_table_query'
    | 'record_create'
    | 'recurrence'
    | 'daily'
    | 'knowledge_management'
    | 'record_create_or_update'
    | 'record_update'
    | 'service_catalog'
    | 'weekly'
    | 'sla_task'
    | 'repeat'
    | 'rest_async'

// Trigger definition
export type TriggerDefinition = Now.Internal.WithIdAndMetadata<{
    name: string
    type: TriggerType
    inputs?: Record<string, Column>
    outputs?: Record<string, Column>
}>

/**
 * @group Flow
 */
export function TriggerDefinition<const T extends TriggerDefinition>(config: T): T {
    return config
}

/**
 * Maps trigger inputs to their TypeScript types with mandatory field support.
 * - If inputs are defined: mandatory fields are required, others are optional
 * - If inputs are undefined: no inputs are allowed (Record<string, never>)
 *
 * Reuses FlowIOType from FlowTypes.ts since Column extends FlowValueType.
 */
export type TriggerInputTypes<T extends TriggerDefinition> =
    T['inputs'] extends Record<string, Column> ? FlowIOType<T['inputs']> : Record<string, never>

/**
 * Helper type to extract the literal table name from actual trigger inputs.
 * This captures the specific table name passed at the call site (e.g., 'incident', 'pa_dashboards').
 */
type ExtractTableFromInputs<TInputs> = TInputs extends { table: infer T } ? (T extends TableName ? T : never) : never

/**
 * Transforms trigger outputs to TypeScript types with dotwalk support for reference columns.
 * For 'current' output, if a table name is provided, the type is enhanced
 * with table-aware fields enabling dot-walking like params.trigger.current.priority
 * For other outputs, ReferenceColumn types get dotwalk support to their referenced tables.
 */
export type TriggerOutputTypes<T extends TriggerDefinition, TTable extends TableName | never = never> =
    T['outputs'] extends Record<string, FlowValueType>
        ? {
              [C in keyof T['outputs']]: C extends 'current'
                  ? TTable extends TableName
                      ? // Table input present, use table-aware type with fallback for undefined schemas
                        TableAwareRecordWithFallback<TTable>
                      : // No table input, apply dotwalk to outputs (handles ReferenceColumn)
                        OutputsWithDotwalk<T['outputs']>[C]
                  : // Non-current outputs use OutputsWithDotwalk (handles ReferenceColumn, FlowObject, FlowArray)
                    OutputsWithDotwalk<T['outputs']>[C]
          }
        : Record<string, never>

/**
 * The output type produced by calling a trigger instance (the return value of `wfa.trigger()`).
 * Contains the trigger's defined outputs, such as `current` and `previous` for record-based triggers.
 * @interface
 */
export type TriggerOutput = ReturnType<TriggerInstance>

/**
 * Trigger instance function that captures the literal table name from inputs.
 * This enables table-aware typing for params.trigger.current when a table is specified.
 *
 * Input fields with mandatory: true are required, all others are optional.
 * Triggers without defined inputs do not accept any inputs.
 * @interface
 */
export type TriggerInstance = <const T extends TriggerDefinition, const TInputs>(
    trigger: T,
    triggerInstanceConfig: Now.Internal.WithID<{
        annotation?: string
    }>,
    inputs: TInputs & TriggerInputTypes<T>
) => TriggerOutputTypes<T, ExtractTableFromInputs<TInputs>>

/** @interface */
export declare const Trigger: TriggerInstance
